/* Anlass der Offenbarung – dt. Zusammenfassungen nach al-Wāḥidī (Asbāb an-Nuzūl) und authentischen Hadith-Sammlungen */
window.ASBAB=[{"s":2,"a":14,"b":14,"g":"w","de":"ʿAbdullāh ibn Ubayy, der Anführer der Heuchler, begrüßte vor seinen Leuten Abū Bakr, ʿUmar und ʿAlī mit großen Lobesworten – und prahlte danach, wie er die Gläubigen täuschte. Darauf kam der Vers über die Heuchler, die vor Gläubigen „Wir glauben“ sagen.","w":11},{"s":2,"a":21,"b":25,"g":"w","de":"ʿAlqama sagte: Wo es im Qur'an „O ihr Menschen“ heißt, ist es meist in Mekka offenbart, wo „O ihr Gläubigen“ steht, in Medina. Diese Verse rufen die Götzendiener Mekkas auf, ihren Schöpfer anzubeten; Vers 25 bringt dann den Gläubigen die frohe Botschaft vom Paradies.","w":28},{"s":2,"a":26,"b":26,"g":"w","de":"Als Allah im Qur'an Gleichnisse mit Mücken, Fliegen und Spinnen nannte, spotteten Heuchler und Gegner: Das klingt nicht wie Allahs Wort. Der Vers antwortet: Allah scheut sich nicht, ein Gleichnis zu prägen, selbst mit einer Mücke.","w":37},{"s":2,"a":44,"b":44,"g":"w","de":"Einige Juden in Medina rieten ihren Verwandten unter den Muslimen: Haltet am Islam fest, er ist die Wahrheit – folgten ihm aber selbst nicht. Der Vers fragt: Befehlt ihr anderen das Gute und vergesst euch selbst?","w":47},{"s":2,"a":62,"b":62,"g":"w","de":"Salmān al-Fārisī erzählte dem Propheten ﷺ von frommen Mönchen, bei denen er gelebt hatte: Sie beteten, fasteten und erwarteten den kommenden Propheten. Er sorgte sich um sie. Dazu kam der Vers: Wer an Allah und den Jüngsten Tag glaubt und Gutes tut, dessen Lohn ist bei seinem Herrn.","w":48},{"s":2,"a":75,"b":75,"g":"w","de":"Der Vers erinnert an Leute aus den Banī Isrāʾīl, die Allahs Wort hörten und es dann wissentlich verdrehten – nach den meisten Gelehrten geht es um jene, die die Beschreibung Muhammads ﷺ und Gebote in ihrer Schrift veränderten.","w":49},{"s":2,"a":79,"b":79,"g":"w","de":"Einige Gelehrte der Schriftbesitzer veränderten die Beschreibung des Propheten ﷺ in ihrem Buch, um ihre Stellung und ihre Einnahmen nicht zu verlieren. Der Vers warnt: Wehe denen, die mit eigener Hand schreiben und sagen: Das ist von Allah.","w":50},{"s":2,"a":80,"b":80,"g":"w","de":"Einige in Medina behaupteten, das Feuer werde sie nur wenige Tage berühren. Der Vers fragt zurück: Habt ihr dazu ein Versprechen von Allah, oder sagt ihr über Allah, was ihr nicht wisst?","w":51},{"s":2,"a":89,"b":89,"g":"w","de":"Vor dem Islam baten die Juden in Medina um Sieg über ihre Gegner – im Namen des Propheten, der kommen sollte. Als er dann kam, glaubten viele nicht an ihn, weil er nicht aus ihrem Volk war. Darauf bezieht sich dieser Vers.","w":52},{"s":2,"a":97,"b":98,"g":"w","de":"ʿUmar ibn al-Khaṭṭāb sprach mit jüdischen Gelehrten. Sie sagten: Dschibrīl ist unser Feind unter den Engeln, Mīkāʾīl unser Freund. ʿUmar antwortete, wer einen von ihnen zum Feind nimmt, ist Feind beider. Kurz danach brachte Dschibrīl genau diese Verse.","src":"Vgl. Buchārī 4480 – Frage des ʿAbdullāh ibn Salām","w":53},{"s":2,"a":99,"b":99,"g":"w","de":"Ibn Ṣūriyā sagte zum Propheten ﷺ: Du hast uns kein klares Zeichen gebracht. Der Vers antwortet: Wir haben dir deutliche Zeichen herabgesandt.","w":54},{"s":2,"a":102,"b":102,"g":"w","de":"Ibn ʿAbbās berichtet: Die Teufel lauschten am Himmel, mischten ein wahres Wort mit vielen Lügen und verbreiteten so Zauberei. Nach dem Tod Sulaimāns behaupteten sie, diese Zauberschriften stammten von ihm. Der Vers stellt klar: Nicht Sulaimān war ungläubig, sondern die Teufel, die Zauberei lehrten.","w":0},{"s":2,"a":104,"b":104,"g":"w","de":"Die Muslime sagten zum Propheten ﷺ „Rāʿinā“ (Achte auf uns). In der Sprache einiger Juden in Medina klang das Wort wie eine Beleidigung, und sie benutzten es zum Spott. Saʿd ibn ʿUbāda bemerkte das. Darauf kam der Vers: Sagt nicht „Rāʿinā“, sondern „Unẓurnā“ (Schau auf uns).","w":1},{"s":2,"a":105,"b":105,"g":"w","de":"Als Muslime ihre jüdischen Verbündeten einluden, an Muhammad ﷺ zu glauben, antworteten diese, sein Ruf sei nicht besser als ihr eigener Glaube. Der Vers zeigt, dass sie den Muslimen das Gute missgönnten.","w":2},{"s":2,"a":108,"b":108,"g":"w","de":"Einige Quraisch forderten vom Propheten ﷺ Wunder als Bedingung für den Glauben: den Hügel Ṣafā in Gold verwandeln, Flüsse in Mekka fließen lassen oder ein Buch vom Himmel herabbringen. Darauf kam dieser Vers, der vor solchen Forderungen warnt, wie sie einst an Mūsā gestellt wurden.","w":3},{"s":2,"a":109,"b":109,"g":"w","de":"Nach der Schlacht von Uḥud sagten einige Juden zu den Muslimen: Wärt ihr im Recht, hättet ihr nicht verloren – kommt zu unserer Religion zurück. Allah offenbarte den Vers und befahl den Muslimen, geduldig zu sein und zu verzeihen.","w":4},{"s":2,"a":113,"b":113,"g":"w","de":"Eine christliche Abordnung aus Nadschrān traf in Medina auf jüdische Gelehrte. Sie stritten heftig: Die einen sagten, die anderen hätten keine wahre Religion – und umgekehrt. Darauf wurde dieser Vers offenbart.","w":5},{"s":2,"a":115,"b":115,"g":"w","de":"Auf einer Reise in dunkler Nacht wussten Gefährten nicht, wo die Qibla lag; jeder betete in die Richtung, die er für richtig hielt. Am Morgen fragten sie den Propheten ﷺ, und es kam der Vers: Allah gehören Osten und Westen. Nach Ibn ʿUmar betrifft der Vers auch das freiwillige Gebet auf dem Reittier (überliefert bei Muslim).","w":6},{"s":2,"a":119,"b":119,"g":"w","de":"Muqātil berichtet, der Prophet ﷺ habe gehofft, seine Gegner würden glauben. Der Vers sagt ihm: Du wirst nicht für die Bewohner des Feuers zur Rechenschaft gezogen – deine Aufgabe ist die frohe Botschaft und die Warnung.","w":7},{"s":2,"a":120,"b":120,"g":"w","de":"Ibn ʿAbbās: Juden in Medina und Christen in Nadschrān hofften, der Prophet ﷺ werde bei ihrer Gebetsrichtung bleiben. Als die Qibla zur Kaaba wechselte, waren sie enttäuscht. Der Vers sagt: Sie werden mit dir erst zufrieden sein, wenn du ihrer Religion folgst.","w":8},{"s":2,"a":125,"b":125,"g":"s","de":"ʿUmar sagte: O Gesandter Allahs, sollten wir nicht am Standort Ibrāhīms (Maqām Ibrāhīm) beten? Darauf kam der Vers: Nehmt den Standort Ibrāhīms als Gebetsstätte. ʿUmar erzählte, dass seine Meinung dreimal mit Allahs Offenbarung übereinstimmte.","src":"Buchārī 402, Muslim 2399"},{"s":2,"a":133,"b":133,"g":"w","de":"Einige Juden behaupteten, Yaʿqūb habe seinen Söhnen vor dem Tod das Judentum ans Herz gelegt. Der Vers antwortet: Wart ihr etwa dabei? Er sagte: Was werdet ihr nach mir anbeten? – Den Gott deiner Väter Ibrāhīm, Ismāʿīl und Isḥāq.","w":9},{"s":2,"a":135,"b":135,"g":"w","de":"Juden- und Christenführer in Medina stritten mit den Muslimen, wessen Religion die beste sei, und forderten: Werdet Juden oder Christen! Der Vers antwortet: Folgt vielmehr dem Glauben Ibrāhīms, des Aufrichtigen.","w":10},{"s":2,"a":142,"b":144,"g":"s","de":"Der Prophet ﷺ betete in Medina 16 oder 17 Monate in Richtung Jerusalem, wünschte sich aber die Kaaba als Qibla. Allah offenbarte: „Wir sehen, wie du dein Gesicht zum Himmel wendest …“ und änderte die Qibla. Einige spotteten: Was hat sie von ihrer Gebetsrichtung abgewandt? Dazu kam: „Allah gehören Osten und Westen.“","src":"Buchārī","w":12},{"s":2,"a":143,"b":143,"g":"s","de":"Als die Gebetsrichtung von Jerusalem zur Kaaba wechselte, fragten die Gefährten: Was ist mit unseren Brüdern, die gestorben sind, während sie nach Jerusalem beteten? Der Vers antwortet: Allah lässt euren Glauben (euer Gebet) nicht verloren gehen.","src":"Buchārī 40 – al-Barāʾ"},{"s":2,"a":146,"b":146,"g":"w","de":"Der Vers handelt von ʿAbdullāh ibn Salām und anderen Schriftbesitzern, die den Propheten ﷺ aus ihren Büchern erkannten. ʿAbdullāh sagte: Ich habe ihn sicherer erkannt als meinen eigenen Sohn.","w":13},{"s":2,"a":158,"b":158,"g":"s","de":"Die Anṣār hatten vor dem Islam die Göttin Manāt verehrt und mieden das Laufen zwischen Ṣafā und Marwa; andere mieden es, weil dort früher Götzen standen. Sie fragten den Propheten ﷺ, und Allah offenbarte: Ṣafā und Marwa gehören zu den Kultzeichen Allahs.","src":"Buchārī, Muslim – von ʿĀʾischa","w":14},{"s":2,"a":159,"b":159,"g":"w","de":"Der Vers betrifft Gelehrte der Schriftbesitzer, die verschwiegen, was in ihrer Schrift über die Steinigung und über Muhammad ﷺ stand.","w":15},{"s":2,"a":168,"b":168,"g":"w","de":"Al-Kalbī: Stämme wie Thaqīf und Khuzāʿa verboten sich selbst bestimmte Tiere und Speisen (Baḥīra, Sāʾiba u. a.). Der Vers sagt: Esst vom Erlaubten und Guten auf der Erde.","w":16},{"s":2,"a":174,"b":174,"g":"w","de":"Al-Kalbī nach Ibn ʿAbbās: Führer der Juden fürchteten, Geschenke und Einfluss zu verlieren, als der Prophet nicht aus ihren Reihen kam. Darum veränderten sie die Beschreibung Muhammads ﷺ in ihrer Schrift. Darauf kam der Vers über die, die die Schrift verbergen.","w":17},{"s":2,"a":187,"b":187,"g":"s","de":"Anfangs durften Fastende nach dem Schlafen in der Nacht nicht mehr essen. Qais ibn Ṣirma, ein Anṣārī, schlief vor dem Essen ein und wurde am nächsten Tag ohnmächtig; auch ʿUmar hatte sich geirrt. Dann kam der Vers, der die ganze Nacht bis zur Morgendämmerung zum Essen und Trinken erlaubt – die Muslime freuten sich sehr.","src":"Buchārī – von al-Barāʾ","w":18},{"s":2,"a":188,"b":188,"g":"w","de":"Zwei Männer stritten vor dem Propheten ﷺ um ein Stück Land, das einer von ihnen unrechtmäßig besaß. Der Vers mahnt: Verzehrt nicht euer Vermögen untereinander auf unrechte Weise.","w":19},{"s":2,"a":189,"b":189,"g":"s","de":"Vor dem Islam betraten die Anṣār nach der Pilgerfahrt ihre Häuser nicht durch die Tür, sondern von hinten – das hielten sie für fromm. Der Vers kam: Frömmigkeit ist nicht, dass ihr von hinten in die Häuser geht, sondern gottesfürchtig zu sein. Geht durch die Türen hinein!","src":"Buchārī 1803, Muslim 3026 – al-Barāʾ"},{"s":2,"a":194,"b":194,"g":"w","de":"Die Muslime wurden im heiligen Monat Dhu-l-Qaʿda bei Ḥudaibiya aufgehalten. Im Jahr darauf durften sie im selben Monat die ʿUmra machen. Der Vers: Der heilige Monat für den heiligen Monat.","w":20},{"s":2,"a":195,"b":195,"g":"s","de":"Als der Islam stark geworden war, sagten einige Anṣār: Jetzt kümmern wir uns wieder um unsere Felder und Güter. Abū Ayyūb al-Anṣārī erklärte: Der Vers „Stürzt euch nicht mit eigener Hand ins Verderben“ kam über uns – das Verderben war, den Einsatz für Allahs Sache aufzugeben.","src":"Abū Dāwūd 2512, Tirmidhī 2972"},{"s":2,"a":197,"b":197,"g":"s","de":"Pilger aus dem Jemen kamen ohne Proviant und sagten: Wir vertrauen auf Allah – in Mekka bettelten sie dann. Darauf kam: Versorgt euch mit Proviant; doch der beste Proviant ist die Gottesfurcht.","src":"Buchārī – von Ibn ʿAbbās","w":21},{"s":2,"a":198,"b":198,"g":"s","de":"Manche dachten, Handel während der Pilgerzeit sei verboten, und mieden die Märkte von ʿUkāẓ und Dhu-l-Madschāz. Der Vers erlaubt es: Es ist keine Sünde, die Gunst eures Herrn (durch Handel) zu suchen.","src":"Buchārī – von Ibn ʿAbbās","w":22},{"s":2,"a":199,"b":199,"g":"s","de":"Die Quraisch hielten sich für etwas Besonderes und standen bei der Pilgerfahrt nicht mit allen anderen am Berg ʿArafāt, sondern blieben in Muzdalifa. Der Vers befiehlt: Zieht von dort weiter, von wo die Menschen weiterziehen – also von ʿArafāt.","src":"Buchārī, Muslim – von ʿĀʾischa","w":23},{"s":2,"a":200,"b":200,"g":"w","de":"Vor dem Islam rühmten sich die Pilger nach dem Ḥaddsch mit ihren Vätern und Ahnen. Der Vers sagt: Gedenkt stattdessen Allahs – so wie ihr eurer Väter gedenkt, oder noch mehr.","w":24},{"s":2,"a":204,"b":205,"g":"w","de":"Al-Akhnas ibn Scharīq kam zum Propheten ﷺ, sprach schöne Worte und gab vor, Muslim zu sein. Doch auf dem Rückweg verbrannte er ein Feld von Muslimen und verletzte ihre Tiere. Über ihn kamen diese Verse: Manche reden schön, aber stiften Unheil auf der Erde.","w":25},{"s":2,"a":207,"b":207,"g":"w","de":"Ṣuhaib ar-Rūmī wollte nach Medina auswandern, doch die Quraisch hielten ihn auf. Er gab ihnen sein ganzes Vermögen in Mekka, damit sie ihn ziehen ließen. Der Prophet ﷺ sagte: Ein gewinnbringender Handel, Abū Yaḥyā! Über ihn kam der Vers: Manche verkaufen sich selbst, um Allahs Wohlgefallen zu erlangen.","w":26},{"s":2,"a":208,"b":208,"g":"w","de":"Einige jüdische Gelehrte, die Muslime geworden waren, wollten zusätzlich weiter Regeln der Tora einhalten, etwa den Sabbat. Darauf kam: O ihr Gläubigen, tretet ganz in den Islam ein.","w":27},{"s":2,"a":217,"b":217,"g":"w","de":"Eine kleine Truppe unter ʿAbdullāh ibn Dschaḥsch traf bei Nakhla auf eine Karawane der Quraisch und kämpfte – am letzten Tag des heiligen Monats Radschab. Die Quraisch warfen den Muslimen vor, den heiligen Monat zu verletzen. Der Vers antwortet: Kämpfen im heiligen Monat ist schwerwiegend – doch Menschen vom Weg Allahs abzubringen und sie aus der heiligen Moschee zu vertreiben, wiegt schwerer.","w":29},{"s":2,"a":220,"b":220,"g":"w","de":"Als Verse über das Vermögen von Waisen kamen, trennten die Leute aus Angst ihr Essen ganz von dem der Waisen – Reste verdarben, und alle litten darunter. Sie fragten den Propheten ﷺ. Der Vers erlaubt: Kümmert euch gut um sie; wenn ihr euch mit ihnen zusammentut, sind sie eure Geschwister.","src":"Abū Dāwūd, Nasāʾī","w":30},{"s":2,"a":221,"b":221,"g":"w","de":"Marthad al-Ghanawī wollte eine Götzendienerin aus Mekka heiraten. Ein anderer Bericht: ʿAbdullāh ibn Rawāḥa befreite eine gläubige Sklavin und heiratete sie, wofür ihn manche tadelten. Der Vers sagt: Heiratet keine Götzendienerinnen, bis sie glauben; eine gläubige Frau ist besser.","w":31},{"s":2,"a":222,"b":222,"g":"s","de":"In Medina mieden manche Leute Frauen während der Monatsblutung völlig – sie aßen nicht einmal mit ihnen. Die Gefährten fragten den Propheten ﷺ. Der Vers kam, und der Prophet ﷺ erklärte: Macht alles gemeinsam wie sonst, nur keine eheliche Nähe in dieser Zeit.","src":"Muslim – von Anas","w":32},{"s":2,"a":224,"b":224,"g":"w","de":"ʿAbdullāh ibn Rawāḥa schwor, nie wieder mit dem Mann seiner Schwester zu sprechen und nicht zwischen den beiden zu versöhnen. Der Vers sagt: Macht Allah nicht durch eure Schwüre zum Hindernis dafür, Gutes zu tun und Frieden zu stiften.","w":33},{"s":2,"a":232,"b":232,"g":"s","de":"Maʿqil ibn Yasār verweigerte seiner geschiedenen Schwester, ihren früheren Mann wieder zu heiraten, obwohl beide es wollten. Der Vers kam: Hindert sie nicht daran. Maʿqil sagte: Jetzt tue ich es, o Gesandter Allahs – und verheiratete sie wieder.","src":"Buchārī","w":34},{"s":2,"a":234,"b":234,"g":"w","de":"Ein Mann aus Ṭāʾif starb in Medina. Der Prophet ﷺ verteilte sein Erbe an Eltern und Kinder und ordnete an, für die Witwe zu sorgen. Dazu kam der Vers über die Wartezeit der Witwen.","w":35},{"s":2,"a":256,"b":256,"g":"w","de":"Frauen der Anṣār, deren Kinder oft starben, hatten gelobt, ein überlebendes Kind bei den Juden aufwachsen zu lassen. Als der Stamm Banū Naḍīr Medina verlassen musste, waren solche Kinder dabei. Die Anṣār wollten sie zum Islam zwingen. Der Vers kam: Es gibt keinen Zwang im Glauben.","src":"Abū Dāwūd – von Ibn ʿAbbās","w":36},{"s":2,"a":260,"b":260,"g":"w","de":"Ibrāhīm sah ein totes Tier am Ufer, das von Fischen, wilden Tieren und Vögeln gefressen und zerstreut wurde. Er bat: Herr, zeig mir, wie Du die Toten lebendig machst – nicht aus Zweifel, sondern damit sein Herz Ruhe findet.","w":38},{"s":2,"a":262,"b":262,"g":"w","de":"Al-Kalbī: Der Vers kam über ʿUthmān ibn ʿAffān und ʿAbd ar-Raḥmān ibn ʿAuf. ʿAbd ar-Raḥmān gab die Hälfte seines Geldes für Bedürftige, ʿUthmān rüstete für den Feldzug nach Tabūk tausend Kamele aus und schenkte den Muslimen einen Brunnen. Der Prophet ﷺ betete für ihn. Der Vers lobt die, die spenden, ohne es vorzuhalten oder zu kränken.","w":39},{"s":2,"a":267,"b":267,"g":"w","de":"Die Anṣār hängten zur Erntezeit Dattelbündel in die Moschee, damit die Armen davon essen konnten. Manche hängten heimlich schlechte Datteln dazwischen. Der Vers sagt: Spendet vom Guten – nicht das Schlechte, das ihr selbst nicht annehmen würdet.","src":"Tirmidhī – von al-Barāʾ","w":40},{"s":2,"a":271,"b":271,"g":"w","de":"Die Gefährten fragten: Ist es besser, heimlich oder offen zu spenden? Der Vers antwortet: Offen zu spenden ist gut, heimlich den Armen zu geben ist noch besser für euch.","w":41},{"s":2,"a":272,"b":272,"g":"w","de":"Manche Muslime wollten nur Muslimen spenden, nicht aber armen Verwandten, die noch keine Muslime waren. Asmāʾ bint Abī Bakr fragte, ob sie ihrer nichtmuslimischen Mutter helfen darf. Der Vers kam: Ihre Rechtleitung ist nicht deine Aufgabe – was ihr an Gutem gebt, ist für euch selbst. Danach halfen sie ihnen.","src":"Vgl. Buchārī 2620 zu Asmāʾ","w":42},{"s":2,"a":274,"b":274,"g":"w","de":"Nach einigen Überlieferungen betrifft der Vers die, die für den Weg Allahs Pferde halten und für sie Tag und Nacht, heimlich und offen ausgeben. Allgemein gilt er für alle, die jederzeit spenden.","w":43},{"s":2,"a":278,"b":279,"g":"w","de":"Nach der Befreiung Mekkas wurden alle Zinsgeschäfte abgeschafft. Ein Stamm von Thaqīf wollte von einem Stamm in Mekka aber noch Zinsen eintreiben. Der Gouverneur schrieb dem Propheten ﷺ, und die Verse kamen: Lasst den Rest des Zinses fallen; ihr bekommt euer Kapital zurück – tut kein Unrecht und erleidet kein Unrecht.","w":44},{"s":2,"a":280,"b":280,"g":"w","de":"Ein Schuldner-Stamm bat um Aufschub bis zur Ernte, weil er in Not war, doch die Gläubiger lehnten ab. Der Vers kam: Ist der Schuldner in Bedrängnis, so gebt ihm Aufschub – und wer ihm die Schuld erlässt, tut noch Besseres.","w":45},{"s":2,"a":285,"b":286,"g":"s","de":"Als Vers 284 kam (Allah rechnet mit euch ab über das, was in euch ist), erschraken die Gefährten: Das können wir nicht tragen! Der Prophet ﷺ sagte: Sagt: Wir hören und gehorchen. Als sie das sagten, offenbarte Allah die letzten beiden Verse von al-Baqara: Allah belastet keine Seele über ihr Vermögen.","src":"Muslim – von Abū Huraira und Ibn ʿAbbās","w":46},{"s":3,"a":12,"b":13,"g":"w","de":"Nach dem Sieg bei Badr warnte der Prophet ﷺ die Juden in Medina. Sie antworteten: Lass dich nicht täuschen, du hast gegen Leute gekämpft, die keine Kriegserfahrung hatten – gegen uns wäre es anders. Darauf kam der Vers: Sag zu denen, die nicht glauben: Ihr werdet besiegt werden. Vers 13 erinnert an Badr als Zeichen.","w":61},{"s":3,"a":23,"b":23,"g":"w","de":"Der Prophet ﷺ lud jüdische Gelehrte ein, die Tora über eine Streitfrage entscheiden zu lassen – sie lehnten ab. Darauf kam der Vers: Hast du nicht die gesehen, denen ein Teil der Schrift gegeben wurde? Sie werden zum Buch Allahs gerufen, und dann wendet sich ein Teil von ihnen ab.","w":79},{"s":3,"a":26,"b":26,"g":"w","de":"Als der Prophet ﷺ seiner Gemeinschaft die Reiche Persiens und Roms verhieß – etwa beim Ausheben des Grabens vor Medina –, spotteten Heuchler: Wie soll er diese mächtigen Reiche je erreichen? Der Vers antwortet: Sag: O Allah, Herr der Herrschaft, Du gibst die Herrschaft, wem Du willst.","w":80},{"s":3,"a":59,"b":59,"g":"w","de":"Die christliche Abordnung aus Nadschrān fragte: Wer ist denn der Vater von ʿĪsā? Kann ein Mensch ohne Vater geboren werden? Der Prophet ﷺ wartete auf Allahs Antwort, und der Vers kam: Das Gleichnis ʿĪsās bei Allah ist wie das Gleichnis Ādams – Er erschuf ihn aus Erde und sprach: Sei!","w":81},{"s":3,"a":61,"b":61,"g":"s","de":"Als die Abordnung aus Nadschrān weiter stritt, forderte der Prophet ﷺ sie auf, gemeinsam Allahs Fluch auf die Lügner herabzurufen (Mubāhala), und brachte al-Ḥasan, al-Ḥusain, Fāṭima und ʿAlī mit. Die Abordnung schreckte zurück und schloss stattdessen einen Vertrag.","src":"Muslim 2404, Buchārī 4380","w":82},{"s":3,"a":65,"b":68,"g":"w","de":"Juden und Christen stritten mit dem Propheten ﷺ, wem Ibrāhīm gehöre – jeder beanspruchte ihn für sich. Der Vers antwortet: Am nächsten stehen Ibrāhīm die, die ihm folgten, dieser Prophet und die Gläubigen.","w":83},{"s":3,"a":69,"b":69,"g":"w","de":"Einige Schriftbesitzer versuchten, Muʿādh ibn Dschabal, Ḥudhaifa und ʿAmmār ibn Yāsir von ihrem Glauben abzubringen. Der Vers sagt: Sie führen damit nur sich selbst in die Irre.","w":84},{"s":3,"a":72,"b":72,"g":"w","de":"Eine Gruppe plante eine List: Morgens zum Schein an den Islam glauben, abends wieder abfallen – damit die Muslime zweifeln. Allah enthüllte den Plan in diesem Vers.","w":85},{"s":3,"a":77,"b":77,"g":"s","de":"Al-Aschʿath ibn Qais stritt mit einem Mann um ein Stück Land, hatte aber keinen Beweis. Der Prophet ﷺ sagte: Wer falsch schwört, um sich fremdes Gut zu nehmen, dem wird Allah zürnen. Dazu kam der Vers über die, die Allahs Bund und ihre Eide für einen geringen Preis verkaufen.","src":"Buchārī 2356, Muslim 138","w":86},{"s":3,"a":83,"b":83,"g":"w","de":"Juden und Christen stritten vor dem Propheten ﷺ, wer Ibrāhīms Religion folgt. Als er sagte, keine der beiden Seiten folge ihr, wurden sie zornig. Der Vers fragt: Begehren sie eine andere als Allahs Religion?","w":87},{"s":3,"a":86,"b":89,"g":"w","de":"Ein Mann aus Medina (al-Ḥārith ibn Suwaid) fiel vom Islam ab und schloss sich den Götzendienern an. Dann bereute er und ließ fragen, ob er zurückkehren dürfe. Die Verse kamen – mit der Ausnahme: außer denen, die danach bereuen. Er kehrte zurück, und der Prophet ﷺ nahm ihn an.","src":"Nasāʾī, Ibn Ḥibbān","w":88},{"s":3,"a":90,"b":90,"g":"w","de":"Nach al-Ḥasan und Qatāda handelt der Vers von Leuten der Schrift, die erst an die Beschreibung des kommenden Propheten glaubten und ihn dann ablehnten, als er kam.","w":89},{"s":3,"a":92,"b":92,"g":"s","de":"Als der Vers kam „Ihr werdet die Frömmigkeit nicht erreichen, bis ihr von dem spendet, was ihr liebt“, stand Abū Ṭalḥa auf und schenkte seinen liebsten Garten Bairuḥāʾ für Allah. Der Prophet ﷺ freute sich und riet ihm, ihn unter seinen Verwandten zu verteilen.","src":"Buchārī 1461, Muslim 998 – Anas"},{"s":3,"a":93,"b":93,"g":"w","de":"Der Prophet ﷺ sagte, er folge der Religion Ibrāhīms. Einige entgegneten: Wie kann das sein, du isst Kamelfleisch! Der Vers antwortet: Alle Speisen waren den Kindern Israels erlaubt – außer dem, was Isrāʾīl (Yaʿqūb) sich selbst verbot.","w":90},{"s":3,"a":96,"b":96,"g":"w","de":"Muslime und Juden stritten, welches Haus größer sei: Jerusalem oder die Kaaba. Der Vers sagt: Das erste Haus, das für die Menschen errichtet wurde, ist das in Bakka (Mekka) – gesegnet und eine Rechtleitung für die Welten.","w":91},{"s":3,"a":100,"b":103,"g":"w","de":"Die Stämme Aus und Khazradsch in Medina waren früher verfeindet, durch den Islam aber Brüder geworden. Ein Mann erinnerte sie mit alten Kriegsgedichten an die Kämpfe – sie gerieten in Streit und griffen sogar zu den Waffen. Der Prophet ﷺ trat zwischen sie und trug diese Verse vor. Da legten sie die Waffen nieder, umarmten sich und weinten.","w":55},{"s":3,"a":101,"b":103,"g":"w","de":"Zwischen den Stämmen Aus und Khazradsch flammte durch Erinnerungen an alte Kriege erneut Streit auf, bis sie die Schwerter zogen. Der Prophet ﷺ kam zu ihnen, und diese Verse wurden offenbart: Wie könnt ihr ungläubig werden, wo euch Allahs Verse vorgetragen werden … Haltet euch alle fest am Seil Allahs und spaltet euch nicht.","w":56},{"s":3,"a":110,"b":110,"g":"w","de":"Zwei jüdische Männer sagten zu Ibn Masʿūd, Ubayy ibn Kaʿb, Muʿādh ibn Dschabal und Sālim: Unsere Religion ist besser als eure. Der Vers antwortet: Ihr seid die beste Gemeinschaft, die für die Menschen hervorgebracht wurde – ihr gebietet das Gute, verbietet das Schlechte und glaubt an Allah.","w":57},{"s":3,"a":111,"b":111,"g":"w","de":"Führer der Juden in Medina beleidigten ʿAbdullāh ibn Salām und seine Gefährten, weil sie Muslime geworden waren. Der Vers tröstet: Sie werden euch nur wenig schaden können.","w":58},{"s":3,"a":113,"b":115,"g":"w","de":"Als ʿAbdullāh ibn Salām und andere Schriftbesitzer Muslime wurden, sagten manche: Nur die Schlechtesten von uns folgen Muhammad. Der Vers widerspricht: Sie sind nicht alle gleich – es gibt unter ihnen Aufrechte, die nachts Allahs Verse lesen und sich niederwerfen. Ibn Masʿūd bezog den Vers auch auf das ʿIschāʾ-Gebet, das die Gläubigen spät in der Nacht beteten.","w":59},{"s":3,"a":118,"b":118,"g":"w","de":"Einige Gläubige waren mit Heuchlern eng befreundet, aus Verwandtschaft, Nachbarschaft oder alten Bündnissen. Der Vers warnt, solche Leute nicht zu engsten Vertrauten zu nehmen, die den Gläubigen schaden wollen.","w":60},{"s":3,"a":121,"b":121,"g":"w","de":"Die Verse ab hier handeln von der Schlacht bei Uḥud. ʿAbd ar-Raḥmān ibn ʿAuf sagte: Wer wissen will, was bei Uḥud geschah, lese die Verse von „Als du frühmorgens von deiner Familie fortzogst …“ bis Vers 154.","w":62},{"s":3,"a":128,"b":128,"g":"s","de":"Bei Uḥud wurde der Prophet ﷺ verletzt: ein Zahn brach, sein Gesicht blutete. Er sagte: Wie kann ein Volk Erfolg haben, das seinen Propheten blutig schlägt, während er es zu seinem Herrn ruft? Auch betete er im Fadschr-Gebet gegen bestimmte Anführer der Gegner. Da kam der Vers: Es ist nicht deine Sache, ob Allah ihnen vergibt oder sie bestraft. Später nahmen manche dieser Männer den Islam an.","src":"Buchārī, Muslim","w":63},{"s":3,"a":135,"b":136,"g":"w","de":"Ein Mann tat etwas Unrechtes, bereute es aber sofort zutiefst, ging in die Berge und bat Allah weinend um Vergebung. Über ihn und alle, die nach einer Sünde an Allah denken und um Verzeihung bitten, kam dieser Vers: Wer vergibt die Sünden außer Allah?","w":64},{"s":3,"a":139,"b":139,"g":"w","de":"Bei Uḥud wollte eine Reiterschar der Gegner einen Hügel über den Muslimen besetzen. Der Prophet ﷺ betete zu Allah um Hilfe. Bogenschützen stiegen hinauf und hielten sie zurück. Dazu kam der Vers: Werdet nicht schwach und seid nicht traurig – ihr werdet die Oberhand haben, wenn ihr gläubig seid.","w":65},{"s":3,"a":140,"b":140,"g":"w","de":"Nach Uḥud kamen Frauen weinend zum Propheten ﷺ, deren Männer und Söhne gefallen waren. Der Vers tröstet: Wenn euch eine Wunde getroffen hat, so hat die anderen eine ähnliche Wunde getroffen. Solche Tage wechseln unter den Menschen.","w":66},{"s":3,"a":151,"b":151,"g":"w","de":"Nach Uḥud wollten die Mekkaner zurückkehren, um die Muslime ganz zu besiegen. Doch Allah warf Furcht in ihre Herzen, und sie zogen weiter nach Mekka. Davon spricht der Vers.","w":67},{"s":3,"a":161,"b":161,"g":"w","de":"Nach Badr fehlte ein rotes Stück Samt aus der Beute, und einige verdächtigten den Propheten ﷺ. Der Vers stellt klar: Es ist für keinen Propheten denkbar, etwas zu unterschlagen.","src":"Abū Dāwūd, Tirmidhī – von Ibn ʿAbbās","w":68},{"s":3,"a":165,"b":165,"g":"w","de":"ʿUmar berichtete: Nach Badr hatten die Muslime Gefangene gegen Lösegeld freigelassen; im Jahr darauf kam bei Uḥud schweres Leid über sie. Der Vers sagt: Es kam von euch selbst.","w":69},{"s":3,"a":169,"b":170,"g":"s","de":"Der Vater von Dschābir fiel bei Uḥud. Der Prophet ﷺ tröstete Dschābir: Allah hat mit deinem Vater ohne Vorhang gesprochen und gesagt: Wünsche dir etwas! Er wünschte, zurückzukehren und noch einmal für Allah zu fallen. Darauf kam: Haltet die auf Allahs Weg Getöteten nicht für tot – sie sind lebendig bei ihrem Herrn.","src":"Tirmidhī 3010, Ibn Mādscha 190"},{"s":3,"a":172,"b":174,"g":"s","de":"Am Tag nach Uḥud rief der Prophet ﷺ die verwundeten und erschöpften Gefährten auf, den Feind zu verfolgen. Leute warnten: Die Mekkaner sammeln sich gegen euch! Sie aber sagten: Allah genügt uns, und Er ist der beste Sachwalter. Darüber kamen diese Verse.","src":"Buchārī – ʿĀʾischa und Ibn ʿAbbās","w":70},{"s":3,"a":179,"b":179,"g":"w","de":"Heuchler spotteten: Muhammad behauptet zu wissen, wer glaubt und wer nicht – dabei kennt er nicht einmal uns. Der Vers antwortet: Allah wird die Guten von den Schlechten trennen; Er lässt euch aber nicht ins Verborgene blicken.","w":71},{"s":3,"a":181,"b":181,"g":"w","de":"Abū Bakr lud einen jüdischen Gelehrten namens Finḥāṣ zum Islam ein und erwähnte das „schöne Darlehen“ für Allah. Finḥāṣ spottete: Dann ist Allah arm und wir sind reich! Abū Bakr wurde zornig. Finḥāṣ leugnete später, das gesagt zu haben. Der Vers bestätigt: Allah hat das Wort derer gehört, die sagten: Allah ist arm.","w":72},{"s":3,"a":183,"b":183,"g":"w","de":"Einige jüdische Anführer sagten: Allah hat uns aufgetragen, keinem Gesandten zu glauben, bis er ein Opfer bringt, das ein Feuer vom Himmel verzehrt. Der Vers antwortet: Gesandte kamen schon früher mit klaren Zeichen und mit dem, was ihr nennt – warum habt ihr sie dann getötet?","w":73},{"s":3,"a":186,"b":186,"g":"s","de":"Der Prophet ﷺ und die Muslime wurden in Medina von Gegnern beleidigt und verspottet, etwa durch den Dichter Kaʿb ibn al-Aschraf und ʿAbdullāh ibn Ubayy. Allah befahl Geduld: Ihr werdet viel Kränkendes hören – seid ihr standhaft und gottesfürchtig, so ist das Entschlossenheit.","src":"Buchārī – von Usāma ibn Zaid","w":74},{"s":3,"a":188,"b":188,"g":"s","de":"Einige Heuchler blieben bei Feldzügen zu Hause, freuten sich darüber und wollten danach gelobt werden für etwas, das sie nicht getan hatten. Darauf kam der Vers.","src":"Buchārī, Muslim – von Abū Saʿīd al-Khudrī","w":75},{"s":3,"a":190,"b":190,"g":"w","de":"Die Quraisch forderten vom Propheten ﷺ ein Wunder: Er solle den Hügel Ṣafā in Gold verwandeln. Der Vers antwortet: In der Schöpfung der Himmel und der Erde und im Wechsel von Nacht und Tag liegen Zeichen für die Verständigen.","w":76},{"s":3,"a":195,"b":195,"g":"s","de":"Umm Salama sagte: O Gesandter Allahs, ich höre nicht, dass Allah bei der Auswanderung die Frauen erwähnt. Darauf kam: Ich lasse keine Tat eines Handelnden unter euch verloren gehen, ob Mann oder Frau.","src":"Tirmidhī 3023"},{"s":3,"a":196,"b":197,"g":"w","de":"Ein Gläubiger sah, wie die Götzendiener in Mekka in Wohlstand lebten, während die Muslime Hunger und Mühe hatten. Der Vers sagt: Lass dich nicht täuschen vom Umherziehen der Ungläubigen im Land – es ist nur ein kurzer Genuss.","w":77},{"s":3,"a":199,"b":199,"g":"s","de":"Als an-Nadschāschī, der König von Abessinien, starb, betete der Prophet ﷺ mit den Gefährten das Totengebet für ihn aus der Ferne. Heuchler spotteten: Er betet für einen fremden Christen! Darauf kam der Vers: Unter den Leuten der Schrift gibt es welche, die an Allah glauben.","src":"Totengebet: Buchārī 1245, Muslim 951","w":78},{"s":4,"a":2,"b":2,"g":"w","de":"Ein Mann verwaltete das große Vermögen seines verwaisten Neffen und wollte es ihm nicht geben, als er erwachsen wurde. Der Vers kam: Gebt den Waisen ihr Vermögen. Der Onkel sagte: Wir gehorchen Allah und Seinem Gesandten – und gab es zurück.","w":105},{"s":4,"a":3,"b":3,"g":"s","de":"ʿĀʾischa erklärte: Manche Vormünder wollten ein Waisenmädchen in ihrer Obhut wegen ihres Vermögens heiraten, ohne ihr eine gerechte Brautgabe zu geben. Der Vers sagt: Wenn ihr fürchtet, den Waisen gegenüber nicht gerecht zu sein, dann heiratet andere Frauen.","src":"Buchārī 4574, Muslim 3018","w":108},{"s":4,"a":6,"b":6,"g":"w","de":"Der Onkel des kleinen Waisen Thābit ibn Rifāʿa fragte den Propheten ﷺ: Was darf ich von seinem Vermögen nehmen, und wann gebe ich es ihm zurück? Der Vers antwortet: Prüft die Waisen, bis sie reif sind – dann gebt ihnen ihr Vermögen.","w":114},{"s":4,"a":7,"b":7,"g":"w","de":"Aus ibn Thābit starb und hinterließ eine Frau und Töchter. Zwei Verwandte nahmen alles Vermögen, denn vor dem Islam erbten nur Männer, die kämpfen konnten. Die Witwe beklagte sich beim Propheten ﷺ. Der Vers kam: Den Männern steht ein Anteil zu – und auch den Frauen.","w":116},{"s":4,"a":11,"b":11,"g":"s","de":"Dschābir ibn ʿAbdillāh war schwer krank; der Prophet ﷺ besuchte ihn und fragte, was mit seinem Vermögen geschehen solle. Auch kam eine Witwe mit zwei Töchtern, deren Onkel ihnen das ganze Erbe genommen hatte. Darauf kamen die Erbverse: Allah schreibt euch vor hinsichtlich eurer Kinder … Der Prophet ﷺ gab den Töchtern zwei Drittel.","src":"Buchārī 4577; Tirmidhī 2092","w":93},{"s":4,"a":22,"b":22,"g":"w","de":"Vor dem Islam heirateten manche Männer nach dem Tod ihres Vaters dessen Witwe. Als ein Sohn das wieder tun wollte, fragte die Frau den Propheten ﷺ. Der Vers verbot es: Heiratet nicht die Frauen, die eure Väter geheiratet hatten.","w":106},{"s":4,"a":33,"b":33,"g":"s","de":"Früher erbten auch Schwurbrüder und angenommene Söhne wie leibliche Verwandte. Der Vers regelt: Das Erbe gehört den nahen Verwandten; Verbündeten gebt einen Anteil durch Vermächtnis und Hilfe.","src":"Buchārī 4580 – Ibn ʿAbbās","w":109},{"s":4,"a":37,"b":39,"g":"w","de":"Nach Ibn ʿAbbās rieten einige Leute den Anṣār: Gebt euer Geld nicht aus, sonst werdet ihr arm. Andere verbargen das Wissen über den Propheten ﷺ aus ihren Schriften. Der Vers tadelt die Geizigen, die anderen Geiz befehlen und verbergen, was Allah ihnen gegeben hat.","w":110},{"s":4,"a":43,"b":43,"g":"s","de":"Bevor Alkohol ganz verboten wurde, betete einmal ein Gefährte nach einem Essen mit Wein vor und las die Verse falsch. Darauf kam: Nähert euch nicht dem Gebet, wenn ihr berauscht seid. Später wurde der Wein ganz verboten (5:90).","src":"Tirmidhī 3026, Abū Dāwūd 3671 – ʿAlī"},{"s":4,"a":51,"b":52,"g":"w","de":"Kaʿb ibn al-Aschraf und Ḥuyayy ibn Akhṭab reisten nach Mekka. Die Quraisch fragten sie: Sind wir besser geleitet oder Muhammad? Obwohl sie Leute der Schrift waren, sagten sie: Ihr seid besser geleitet. Darauf kamen diese Verse.","w":111},{"s":4,"a":59,"b":59,"g":"s","de":"Der Vers „Gehorcht Allah, dem Gesandten und denen unter euch, die Befehlsgewalt haben“ wurde über ʿAbdullāh ibn Ḥudhāfa offenbart, den der Prophet ﷺ als Anführer einer Truppe schickte. Wenn ihr über etwas streitet, bringt es vor Allah und den Gesandten.","src":"Buchārī 4584, Muslim 1834","w":113},{"s":4,"a":60,"b":62,"g":"w","de":"Bei einem Streit um Besitz wollte ein Mann, der sich Muslim nannte, nicht zum Propheten ﷺ gehen, sondern zu einem Wahrsager, damit der für ihn entscheide. Die Verse tadeln, wer sich angeblich zum Glauben bekennt, aber Urteil bei falschen Mächten sucht.","w":115},{"s":4,"a":65,"b":65,"g":"s","de":"Az-Zubair und ein Mann aus Medina stritten um das Bewässern ihrer Palmen. Der Prophet ﷺ entschied, doch der andere warf ihm vor, er bevorzuge seinen Cousin. Der Vers kam: Bei deinem Herrn – sie glauben nicht wirklich, bis sie dich zum Richter nehmen und sich deinem Urteil ganz fügen.","src":"Buchārī 2359, Muslim 2357"},{"s":4,"a":77,"b":77,"g":"w","de":"In Mekka wollten einige Gefährten gegen ihre Peiniger kämpfen, doch der Prophet ﷺ sagte: Haltet eure Hände zurück. Als später in Medina der Kampf erlaubt wurde, fiel es manchen schwer. Darauf kam dieser Vers.","src":"Nasāʾī 3086 – Ibn ʿAbbās","w":117},{"s":4,"a":78,"b":78,"g":"w","de":"Nach Uḥud sagten Heuchler: Wären unsere Brüder bei uns geblieben, wären sie nicht gestorben. Der Vers antwortet: Wo immer ihr seid, wird euch der Tod einholen, selbst in hohen Burgen.","w":118},{"s":4,"a":88,"b":88,"g":"s","de":"Eine Gruppe zog mit dem Propheten ﷺ nach Uḥud aus, kehrte dann aber um. Die Gefährten waren uneins, wie man über sie urteilen solle. Der Vers kam: Warum seid ihr wegen der Heuchler in zwei Gruppen gespalten?","src":"Buchārī 4589, Muslim 2776 – Zaid ibn Thābit","w":119},{"s":4,"a":92,"b":92,"g":"w","de":"ʿAyyāsch ibn Abī Rabīʿa tötete einen Mann, der ihn früher gequält hatte – ohne zu wissen, dass dieser inzwischen Muslim geworden war. Der Vers regelt die Tötung aus Versehen: Blutgeld an die Familie und Befreiung eines Gläubigen oder zwei Monate Fasten.","w":120},{"s":4,"a":93,"b":93,"g":"w","de":"Ein Mann nahm das Blutgeld für seinen getöteten Bruder an, tötete dann aber hinterlistig den Boten und fiel vom Islam ab. Der Vers warnt eindringlich: Wer einen Gläubigen absichtlich tötet, dessen Lohn ist die Hölle.","w":121},{"s":4,"a":94,"b":94,"g":"s","de":"Auf einem Feldzug grüßte ein Mann die Muslime mit „As-salāmu ʿalaikum“, doch einige meinten, er sage das nur aus Angst, und töteten ihn. Der Vers kam: Sagt nicht zu dem, der euch den Friedensgruß entbietet: Du bist kein Gläubiger.","src":"Buchārī 4591, Muslim 3025 – Ibn ʿAbbās"},{"s":4,"a":95,"b":95,"g":"s","de":"Als der Vers kam „Nicht gleich sind die Gläubigen, die daheim bleiben, und die, die sich auf Allahs Weg einsetzen“, fragte der blinde ʿAbdullāh ibn Umm Maktūm: Und ich, der ich nicht sehen kann? Noch in derselben Sitzung kamen die Worte hinzu: „außer denen, die eine Beeinträchtigung haben“. Zaid ibn Thābit schrieb sie auf.","src":"Buchārī 4592","w":122},{"s":4,"a":97,"b":97,"g":"s","de":"Einige in Mekka bekannten sich zum Islam, wanderten aber nicht aus und zogen sogar mit den Mekkanern gegen die Muslime nach Badr, wo sie fielen. Darüber kam dieser Vers.","src":"Buchārī 4596 – Ibn ʿAbbās","w":123},{"s":4,"a":101,"b":102,"g":"w","de":"Bei ʿUsfān betete der Prophet ﷺ mit den Gefährten das Dhuhr-Gebet, während die Gegner unter Khālid ibn al-Walīd in Sichtweite standen. Sie planten, beim ʿAṣr-Gebet anzugreifen. Zwischen Dhuhr und ʿAṣr brachte Dschibrīl diesen Vers über das Gebet in Gefahr: Eine Gruppe betet, die andere wacht.","src":"Abū Dāwūd, Nasāʾī","w":92},{"s":4,"a":105,"b":116,"g":"w","de":"Ein Mann namens Ṭuʿma stahl eine Rüstung und versteckte sie bei einem jüdischen Nachbarn, um ihn als Dieb dastehen zu lassen. Seine Sippe bat den Propheten ﷺ, ihn zu verteidigen. Da kamen diese Verse: Sei kein Fürsprecher der Betrüger – und der unschuldige Jude wurde freigesprochen. Gerechtigkeit gilt für alle.","src":"Tirmidhī 3036","w":94},{"s":4,"a":123,"b":125,"g":"w","de":"Muslime und Leute der Schrift stritten: Unser Prophet war zuerst! – Unser Prophet ist der letzte! Der Vers sagt: Es geht nicht nach euren Wünschen. Wer Böses tut, wird dafür belangt; wer Gutes tut, Mann oder Frau, und gläubig ist, kommt ins Paradies.","w":95},{"s":4,"a":127,"b":127,"g":"s","de":"Die Leute fragten nach den Rechten von Frauen, besonders von Waisenmädchen. Manche Vormünder wollten reiche, schöne Waisen heiraten, ohne ihnen eine gerechte Brautgabe zu geben, und vernachlässigten die armen. Der Vers erinnert: Behandelt Waisen gerecht.","src":"Buchārī, Muslim – von ʿĀʾischa","w":96},{"s":4,"a":128,"b":128,"g":"s","de":"Eine Frau befürchtete, ihr Mann wolle sich von ihr trennen. Sie bot an, auf einige ihrer Rechte zu verzichten, um bei ihm und den Kindern zu bleiben. Der Vers erlaubt eine solche Einigung: Versöhnung ist besser.","src":"Buchārī 2694 – von ʿĀʾischa","w":97},{"s":4,"a":135,"b":135,"g":"w","de":"Al-Suddī: Ein Armer und ein Reicher kamen mit einem Streit zum Propheten ﷺ. Man neigt dazu, dem Armen recht zu geben. Der Vers stellt klar: Steht fest für Gerechtigkeit – ob es um einen Reichen oder einen Armen geht.","w":98},{"s":4,"a":148,"b":148,"g":"w","de":"Ein Gast wurde von Leuten schlecht bewirtet und beklagte sich darüber. Der Vers erlaubt es dem, dem Unrecht geschah, offen darüber zu sprechen – sonst liebt Allah keine üblen Worte in der Öffentlichkeit.","w":99},{"s":4,"a":153,"b":153,"g":"w","de":"Einige Juden sagten zum Propheten ﷺ: Wenn du wirklich ein Prophet bist, dann bring uns ein ganzes Buch vom Himmel, wie Mūsā es tat. Darauf kam dieser Vers.","w":100},{"s":4,"a":166,"b":166,"g":"w","de":"Führer aus Mekka sagten: Wir haben die Juden nach dir gefragt, sie kennen dich nicht – bring jemanden, der bezeugt, dass Allah dich gesandt hat. Der Vers antwortet: Allah selbst bezeugt, was Er dir herabgesandt hat, und die Engel bezeugen es.","w":101},{"s":4,"a":171,"b":171,"g":"w","de":"Der Vers richtet sich an Christen, die sagten, ʿĪsā sei Allahs Sohn: Übertreibt nicht in eurer Religion und sagt über Allah nur die Wahrheit – ʿĪsā ist Allahs Gesandter und Sein Wort.","w":102},{"s":4,"a":172,"b":172,"g":"w","de":"Die Abordnung aus Nadschrān fragte: Warum sagst du, ʿĪsā sei Allahs Diener? Das ist eine Schande für ihn! Der Vers antwortet: Der Messias wird es niemals verschmähen, Allahs Diener zu sein – und auch nicht die nahestehenden Engel.","w":103},{"s":4,"a":176,"b":176,"g":"s","de":"Dschābir ibn ʿAbdillāh war schwer krank und hatte nur Schwestern als Erben. Er fragte den Propheten ﷺ, wie er sein Vermögen verteilen solle. Darauf kam der letzte Vers von an-Nisāʾ über das Erbe der „Kalāla“ – wer weder Eltern noch Kinder hinterlässt. Dschābir wurde wieder gesund.","src":"Buchārī 194, Muslim 1616","w":104},{"s":5,"a":2,"b":2,"g":"w","de":"Ein Mann namens al-Ḥuṭam täuschte Interesse am Islam vor und stahl dann Kamele aus Medina. Später kam er als Pilger nach Mekka, und einige Muslime wollten ihn angreifen. Der Vers verbietet, die Kultzeichen Allahs und die Pilger zum Heiligen Haus anzutasten.","w":126},{"s":5,"a":3,"b":3,"g":"s","de":"Ein jüdischer Gelehrter sagte zu ʿUmar: In eurem Buch steht ein Vers – wäre er bei uns herabgekommen, hätten wir den Tag zum Fest gemacht: „Heute habe Ich euch eure Religion vervollkommnet.“ ʿUmar sagte: Ich weiß genau, wann und wo er herabkam – am Tag von ʿArafa, an einem Freitag, als der Prophet ﷺ in ʿArafāt stand.","src":"Buchārī 45, Muslim 3017"},{"s":5,"a":4,"b":4,"g":"w","de":"Die Gefährten fragten, welche Jagdtiere sie verwenden dürfen. Der Vers antwortet: Erlaubt sind euch die guten Dinge – und was abgerichtete Jagdtiere für euch fangen, wenn ihr dabei Allahs Namen nennt.","w":129},{"s":5,"a":6,"b":6,"g":"s","de":"Auf einer Reise verlor ʿĀʾischa ihre Halskette. Alle warteten an einem Ort ohne Wasser, und die Gebetszeit kam. Da offenbarte Allah den Vers über den Tayammum. Usaid ibn Ḥuḍair sagte: Das ist nicht der erste Segen, der durch euch kommt, o Familie Abū Bakrs!","src":"Buchārī 334, Muslim 367"},{"s":5,"a":11,"b":11,"g":"s","de":"Ein Mann namens Ghauraṯ schlich sich an den Propheten ﷺ heran, als dieser unter einem Baum ruhte, nahm sein Schwert und fragte: Wer schützt dich jetzt vor mir? Der Prophet ﷺ sagte: Allah. Da konnte der Mann nichts tun und steckte das Schwert wieder ein. Der Vers erinnert: Gedenkt der Gnade Allahs, als Leute ihre Hände gegen euch ausstrecken wollten.","src":"Vorfall: Buchārī 4139, Muslim 843","w":125},{"s":5,"a":41,"b":47,"g":"s","de":"Einige Gelehrte hatten die Strafe, die in der Tora stand, für vornehme Leute heimlich ersetzt. Der Prophet ﷺ fragte nach dem Urteil der Tora, und ein Gelehrter gab es zu. Die Verse sprechen davon, dass man nach dem urteilen muss, was Allah herabgesandt hat.","src":"Muslim 1700 – al-Barāʾ","w":130},{"s":5,"a":49,"b":49,"g":"w","de":"Einige Anführer boten dem Propheten ﷺ an, an ihn zu glauben, wenn er in einem Streit zu ihren Gunsten entscheidet. Er lehnte ab. Der Vers: Urteile nach dem, was Allah herabgesandt hat, und hüte dich vor ihnen, dass sie dich nicht davon abbringen.","w":131},{"s":5,"a":57,"b":57,"g":"w","de":"Zwei Männer gaben sich als Muslime aus, waren aber Heuchler und machten sich über den Glauben lustig. Einige Muslime waren mit ihnen befreundet. Der Vers warnt, solche Spötter zu Vertrauten zu nehmen.","w":132},{"s":5,"a":58,"b":58,"g":"w","de":"Wenn der Gebetsruf erklang und die Muslime zum Gebet aufstanden, machten sich einige darüber lustig. Darauf kam der Vers: Wenn ihr zum Gebet ruft, nehmen sie es zum Spott – weil sie Leute sind, die nicht begreifen.","w":133},{"s":5,"a":59,"b":59,"g":"w","de":"Einige fragten den Propheten ﷺ, an welche Gesandten er glaubt. Als er auch ʿĪsā nannte, sagten sie: Wir kennen keine schlechtere Religion als eure. Der Vers antwortet: Was werft ihr uns vor – außer, dass wir an Allah und an alles glauben, was herabgesandt wurde?","w":134},{"s":5,"a":82,"b":86,"g":"w","de":"Als die Muslime in Mekka verfolgt wurden, schickte der Prophet ﷺ einige Gefährten zu an-Nadschāschī nach Abessinien – einem gerechten König. Als sie ihm und seinen Priestern Qur'an vorlasen, flossen ihnen die Tränen, weil sie die Wahrheit erkannten. Darüber kamen diese Verse.","w":135},{"s":5,"a":87,"b":88,"g":"s","de":"Einige Gefährten wollten nach einer Ermahnung nur noch fasten, die ganze Nacht beten und auf Fleisch, Schlaf und Familienleben verzichten. Der Vers kam: Verbietet euch nicht die guten Dinge, die Allah erlaubt hat. Der Prophet ﷺ sagte: Ich bete und schlafe, faste und esse.","src":"Vgl. Buchārī 5063","w":136},{"s":5,"a":90,"b":91,"g":"s","de":"ʿUmar betete: O Allah, gib uns eine klare Regel zum Wein! Erst kam 2:219, dann 4:43, und er betete weiter. Schließlich kamen diese Verse: Wein, Glücksspiel … sind ein Gräuel – werdet ihr nun aufhören? ʿUmar sagte: Wir haben aufgehört!","src":"Abū Dāwūd 3670, Tirmidhī 3049"},{"s":5,"a":93,"b":93,"g":"s","de":"Als der Wein verboten wurde, schüttete man ihn in Medina auf die Straßen. Einige fragten: Was ist mit unseren Brüdern, die gestorben sind, als Wein noch erlaubt war? Der Vers kam: Keine Sünde trifft die Gläubigen für das, was sie früher gegessen oder getrunken haben.","src":"Buchārī 4620, Muslim 1980 – Anas","w":137},{"s":5,"a":101,"b":101,"g":"s","de":"Manche stellten dem Propheten ﷺ unnötige oder spöttische Fragen, z. B. „Wo ist meine verlorene Kamelstute?“ oder „Wer ist mein Vater?“. Der Vers kam: Fragt nicht nach Dingen, die euch, wenn sie euch offengelegt würden, Kummer bereiten.","src":"Buchārī 4621–4622, Muslim 2359"},{"s":5,"a":106,"b":108,"g":"s","de":"Ein Mann starb auf Reisen und gab seine Sachen zwei Begleitern mit. Sie behielten heimlich einen silbernen Becher mit Gold. Später tauchte der Becher in Mekka auf. Die Verse regeln Zeugen beim Testament auf Reisen und Eide, wenn Betrug herauskommt.","src":"Buchārī 2780 – Ibn ʿAbbās","w":124},{"s":6,"a":7,"b":7,"g":"w","de":"Die Götzendiener Mekkas sagten: Wir glauben erst, wenn du ein Buch von Allah bringst, begleitet von vier Engeln als Zeugen. Der Vers sagt: Selbst wenn Wir ein Buch auf Pergament herabsandten, das sie anfassen könnten, würden sie sagen: Das ist nur Zauberei.","w":146},{"s":6,"a":25,"b":25,"g":"w","de":"Führer der Quraisch hörten dem Propheten ﷺ beim Rezitieren zu. Einer von ihnen, an-Naḍr, sagte: Das sind nur Geschichten der Früheren. Darauf kam der Vers: Manche hören dir zu, doch Wir haben Hüllen auf ihre Herzen gelegt.","w":142},{"s":6,"a":26,"b":26,"g":"w","de":"Nach Ibn ʿAbbās handelt der Vers von denen, die andere vom Propheten ﷺ fernhielten und sich selbst von ihm fernhielten. Nach einer anderen Meinung ist Abū Ṭālib gemeint, der den Propheten ﷺ beschützte, aber den Glauben nicht annahm.","w":143},{"s":6,"a":33,"b":33,"g":"w","de":"Abū Dschahl gab einmal zu: Muhammad hat nie gelogen – aber wenn sein Stamm auch noch das Prophetentum bekommt, was bleibt für uns? Der Vers tröstet den Propheten ﷺ: Sie erklären nicht dich zum Lügner, sondern leugnen Allahs Zeichen.","src":"Tirmidhī 3064","w":144},{"s":6,"a":52,"b":52,"g":"s","de":"Vornehme Mekkaner verlangten: Schick diese armen Leute weg, dann setzen wir uns zu dir. Gemeint waren Saʿd ibn Abī Waqqāṣ, Ibn Masʿūd, Bilāl und andere. Der Vers kam: Weise die nicht ab, die morgens und abends ihren Herrn anrufen.","src":"Muslim 2413 – Saʿd"},{"s":6,"a":57,"b":57,"g":"w","de":"Führer der Quraisch forderten spöttisch: Bring doch die Strafe, mit der du uns drohst! Der Vers antwortet: Ich stehe auf einem klaren Beweis von meinem Herrn – das, was ihr beschleunigen wollt, liegt nicht bei mir.","w":145},{"s":6,"a":82,"b":82,"g":"s","de":"Als der Vers kam „Die glauben und ihren Glauben nicht mit Unrecht vermischen …“, erschraken die Gefährten: Wer von uns tut sich kein Unrecht? Der Prophet ﷺ erklärte: Gemeint ist der Schirk – wie Luqmān sagte: Schirk ist ein gewaltiges Unrecht (31:13).","src":"Buchārī 32, Muslim 124"},{"s":6,"a":100,"b":100,"g":"w","de":"Manche glaubten, Allah und der Teufel seien zwei Brüder, die je einen Teil der Schöpfung erschaffen hätten. Der Vers weist das zurück: Sie geben Allah die Dschinn zu Partnern – dabei hat Er sie erschaffen.","w":138},{"s":6,"a":108,"b":108,"g":"w","de":"Die Götzendiener drohten: Hört auf, unsere Götzen zu beschimpfen, sonst beschimpfen wir euren Herrn. Der Vers sagt: Beschimpft nicht, was sie neben Allah anrufen, damit sie nicht aus Unwissenheit Allah beschimpfen.","w":139},{"s":6,"a":109,"b":111,"g":"w","de":"Die Quraisch forderten: Verwandle den Hügel Ṣafā in Gold, dann glauben wir. Dschibrīl sagte: Wenn ein solches Zeichen kommt und sie dann nicht glauben, folgt die Strafe. Der Prophet ﷺ wollte ihnen lieber Zeit lassen, damit manche bereuen. Dazu kamen diese Verse.","w":140},{"s":6,"a":121,"b":121,"g":"w","de":"Götzendiener wollten die Muslime verwirren: Was ihr schlachtet, esst ihr – aber was Allah sterben lässt (verendete Tiere), esst ihr nicht? Der Vers antwortet: Esst nicht von dem, worüber Allahs Name nicht genannt wurde – die Teufel flüstern ihren Freunden ein, mit euch zu streiten.","src":"Abū Dāwūd 2818","w":141},{"s":7,"a":175,"b":176,"g":"w","de":"Der Vers erzählt von einem Mann, dem Allah Wissen gegeben hatte, der sich aber davon abwandte und seinen Gelüsten folgte – nach vielen Gelehrten Balʿam ibn Bāʿūrāʾ zur Zeit Mūsās, der auf Drängen seines Volkes gegen Mūsā betete.","w":147},{"s":7,"a":187,"b":187,"g":"w","de":"Einige fragten den Propheten ﷺ: Wenn du ein Prophet bist, sag uns, wann die Stunde kommt! Der Vers antwortet: Das Wissen darüber ist allein bei meinem Herrn – sie kommt plötzlich.","w":148},{"s":7,"a":188,"b":188,"g":"w","de":"Die Leute Mekkas fragten spöttisch: Sagt dein Herr dir nicht, wann die Preise steigen, damit du Gewinn machst? Der Vers antwortet: Ich habe für mich selbst weder Nutzen noch Schaden in der Hand – außer was Allah will. Ich bin nur ein Warner und Überbringer froher Botschaft.","w":149},{"s":8,"a":1,"b":1,"g":"w","de":"Nach Badr stritten die jungen Kämpfer, die vorne gekämpft hatten, und die Älteren, die bei den Fahnen geblieben waren, um die Beute. Auch Saʿd ibn Abī Waqqāṣ wollte ein erbeutetes Schwert behalten. Die Sure al-Anfāl begann: Die Beute gehört Allah und dem Gesandten – fürchtet Allah und stiftet Frieden untereinander.","src":"Abū Dāwūd 2737; Muslim 1748","w":151},{"s":8,"a":19,"b":19,"g":"w","de":"Vor Badr betete Abū Dschahl: O Allah, vernichte heute die Seite, die die Verwandtschaft zerreißt und Neues bringt! Der Vers antwortet: Wenn ihr eine Entscheidung erbeten habt – nun ist die Entscheidung zu euch gekommen.","w":152},{"s":8,"a":27,"b":27,"g":"w","de":"Abū Lubāba verriet den Banū Quraiẓa durch eine Geste eine geheime Entscheidung der Muslime. Sofort bereute er, band sich an eine Säule der Moschee und wollte weder essen noch trinken, bis Allah ihm vergibt. Der Vers kam: Verratet nicht Allah und den Gesandten. Später nahm Allah seine Reue an.","w":153},{"s":8,"a":32,"b":33,"g":"s","de":"Abū Dschahl sagte spottend: O Allah, wenn das die Wahrheit von Dir ist, dann lass Steine vom Himmel auf uns regnen! Darauf kam: Allah wird sie nicht bestrafen, solange du unter ihnen bist und solange sie um Vergebung bitten.","src":"Buchārī 4648, Muslim 2796 – Anas","w":154},{"s":8,"a":35,"b":35,"g":"w","de":"Vor dem Islam umrundeten manche die Kaaba mit Pfeifen und Händeklatschen. Der Vers sagt: Ihr „Gebet“ am Haus war nur Pfeifen und Klatschen.","w":155},{"s":8,"a":36,"b":36,"g":"w","de":"Führer der Quraisch gaben viel Geld aus, um Heere gegen den Propheten ﷺ auszurüsten, etwa für Badr und Uḥud. Der Vers sagt: Sie geben ihr Vermögen aus, um vom Weg Allahs abzuhalten – es wird ihnen zum Bedauern werden.","w":156},{"s":8,"a":64,"b":64,"g":"w","de":"Nach einer Überlieferung kam der Vers, als ʿUmar den Islam annahm und die Gläubigen damit vierzig wurden: O Prophet, Allah genügt dir und den Gläubigen, die dir folgen.","w":157},{"s":8,"a":67,"b":69,"g":"s","de":"Nach Badr beriet sich der Prophet ﷺ über die Gefangenen. Abū Bakr riet zu Lösegeld, ʿUmar zu Strenge. Der Prophet ﷺ nahm Lösegeld. Dann kamen diese Verse, die ʿUmars Meinung bestätigten, aber die Beute dennoch erlaubten.","src":"Muslim 1763 – Ibn ʿAbbās von ʿUmar","w":158},{"s":8,"a":70,"b":70,"g":"w","de":"Al-ʿAbbās, der Onkel des Propheten ﷺ, war bei Badr gefangen und musste Lösegeld zahlen. Er klagte, nun sei er arm. Der Vers tröstet: Wenn Allah in euren Herzen Gutes weiß, gibt Er euch Besseres, als euch genommen wurde. Später sagte al-ʿAbbās, Allah habe ihm viel mehr gegeben.","w":159},{"s":9,"a":12,"b":12,"g":"w","de":"Ibn ʿAbbās: Der Vers bezieht sich auf die Anführer der Quraisch, die ihren Vertrag brachen und planten, den Propheten ﷺ zu vertreiben.","w":164},{"s":9,"a":17,"b":18,"g":"w","de":"Als al-ʿAbbās bei Badr gefangen war, warfen ihm Muslime seinen Unglauben vor. Er sagte: Wir pflegen doch die heilige Moschee und tränken die Pilger! Der Vers antwortet: Es steht den Götzendienern nicht zu, Allahs Moscheen zu pflegen.","w":166},{"s":9,"a":19,"b":19,"g":"s","de":"An einem Freitag stritten Männer beim Minbar: Der eine sagte, Pilger zu tränken sei das Beste, der andere, die Moschee zu pflegen, der dritte, der Einsatz auf Allahs Weg. ʿUmar wollte den Propheten ﷺ fragen – da kam der Vers: Stellt ihr das Tränken der Pilger dem gleich, der an Allah glaubt und sich einsetzt?","src":"Muslim 1879","w":167},{"s":9,"a":23,"b":24,"g":"w","de":"Als die Auswanderung nach Medina befohlen wurde, hielten manche ihre Familien zurück und baten: Lass uns nicht allein! Einige blieben deshalb in Mekka. Die Verse mahnen: Allah, Sein Gesandter und Sein Weg müssen euch lieber sein als Väter, Kinder, Geschwister und Besitz.","w":168},{"s":9,"a":34,"b":35,"g":"s","de":"Der Vers über die, die Gold und Silber horten und nicht auf Allahs Weg ausgeben: Abū Dharr meinte, er gelte für alle, auch für Muslime – Muʿāwiya meinte, nur für Schriftbesitzer.","src":"Buchārī 1406","w":169},{"s":9,"a":38,"b":38,"g":"w","de":"Vor dem Feldzug nach Tabūk war es sehr heiß, die Datteln waren reif, und das Land litt unter Dürre. Viele wollten lieber im Schatten bleiben. Der Vers ermahnt: Was ist mit euch, wenn euch gesagt wird: Zieht aus auf Allahs Weg – und ihr hängt schwer an der Erde?","w":170},{"s":9,"a":41,"b":41,"g":"w","de":"Manche entschuldigten sich wegen ihrer Felder und Arbeit. Der Vers: Zieht aus, leicht oder schwer. Abū Ṭalḥa sagte: Allah hat niemanden ausgenommen – und zog trotz hohen Alters mit. Später erleichterte Vers 91 die Pflicht für Schwache und Kranke.","w":171},{"s":9,"a":42,"b":47,"g":"w","de":"Als der Prophet ﷺ nach Tabūk aufbrach, blieben ʿAbdullāh ibn Ubayy und die Heuchler zurück. Allah tröstete ihn: Wäre es eine nahe Beute und eine leichte Reise gewesen, wären sie dir gefolgt – und wären sie mitgezogen, hätten sie nur Unruhe gestiftet.","w":172},{"s":9,"a":49,"b":49,"g":"w","de":"Der Heuchler al-Dschadd ibn Qais bat, zu Hause bleiben zu dürfen, mit einer fadenscheinigen Ausrede. Der Vers sagt: Manche sagen: Gib mir Erlaubnis und bring mich nicht in Versuchung – doch sie sind schon in die Versuchung gefallen.","w":173},{"s":9,"a":58,"b":58,"g":"s","de":"Als der Prophet ﷺ Güter verteilte, sagte ein Mann: Sei gerecht, o Gesandter Allahs! Er antwortete: Wehe dir, wer soll denn gerecht sein, wenn ich es nicht bin? Darauf kam der Vers über die, die ihn wegen der Verteilung der Almosen tadeln.","src":"Buchārī 6933 – Abū Saʿīd","w":174},{"s":9,"a":61,"b":61,"g":"w","de":"Heuchler redeten schlecht über den Propheten ﷺ. Als jemand warnte, es könnte ihm zu Ohren kommen, sagten sie: Er ist ganz Ohr – er glaubt alles, was man ihm erzählt. Der Vers antwortet: Er ist ein Ohr zum Guten für euch – er glaubt an Allah und vertraut den Gläubigen.","w":175},{"s":9,"a":64,"b":64,"g":"w","de":"Die Heuchler fürchteten, es könnte eine Sure herabkommen, die enthüllt, was in ihren Herzen ist. Davon spricht der Vers.","w":176},{"s":9,"a":65,"b":66,"g":"w","de":"Auf dem Weg nach Tabūk spotteten einige Heuchler über den Propheten ﷺ und die Qur'an-Leser. Als sie zur Rede gestellt wurden, sagten sie: Wir haben nur gescherzt. Der Vers antwortet: Habt ihr etwa über Allah, Seine Zeichen und Seinen Gesandten gespottet? Entschuldigt euch nicht.","w":177},{"s":9,"a":74,"b":74,"g":"w","de":"Heuchler redeten auf dem Feldzug nach Tabūk heimlich gegen den Propheten ﷺ und den Islam; ʿAbdullāh ibn Ubayy sagte sogar: Wenn wir nach Medina zurückkehren, wird der Mächtige den Schwachen hinaustreiben. Als man sie fragte, schworen sie, nichts gesagt zu haben. Der Vers entlarvt sie: Sie schwören bei Allah, es nicht gesagt zu haben – doch sie haben es gesagt.","w":178},{"s":9,"a":79,"b":79,"g":"s","de":"Als die Gefährten zum Spenden aufgerufen wurden, gab einer viel – und Heuchler sagten: Er will nur gesehen werden. Ein armer Mann brachte ein kleines Maß Datteln, das er durch Lastentragen verdient hatte – da spotteten sie: Allah braucht sein bisschen nicht. Der Vers verurteilt diesen Spott.","src":"Buchārī 1415 – Abū Masʿūd","w":180},{"s":9,"a":84,"b":84,"g":"s","de":"Als ʿAbdullāh ibn Ubayy, der Anführer der Heuchler, starb, bat sein gläubiger Sohn den Propheten ﷺ um sein Hemd als Leichentuch und um das Totengebet. Der Prophet ﷺ betete für ihn, obwohl ʿUmar ihn zurückhalten wollte. Dann kam der Vers: Bete niemals für einen von ihnen, der stirbt.","src":"Buchārī 1269, Muslim 2400","w":181},{"s":9,"a":92,"b":92,"g":"w","de":"Arme Gefährten wollten unbedingt mit nach Tabūk, hatten aber keine Reittiere. Der Prophet ﷺ sagte: Ich habe nichts, worauf ich euch tragen kann. Sie gingen weinend fort. Der Vers lobt sie: Ihre Augen flossen über vor Trauer, weil sie nichts zum Ausgeben fanden – sie trifft kein Vorwurf.","w":182},{"s":9,"a":97,"b":97,"g":"w","de":"Der Vers spricht von Beduinenstämmen rund um Medina, unter denen damals viele Heuchler waren; er zeigt, wie fern sie dem Wissen um Allahs Gebote waren. Im folgenden Vers werden auch gläubige Beduinen gelobt.","w":183},{"s":9,"a":101,"b":101,"g":"w","de":"Der Vers warnt: Unter den Beduinen um Medina und unter den Bewohnern Medinas gibt es Heuchler, die du nicht kennst – Wir aber kennen sie.","w":160},{"s":9,"a":102,"b":103,"g":"w","de":"Einige Männer waren dem Feldzug nach Tabūk ferngeblieben und bereuten es bitter. Sie banden sich an die Säulen der Moschee, bis der Prophet ﷺ sie selbst losbinde. Er wartete auf Allahs Befehl – dann kam der Vers über die, die ihre Sünden bekennen, und er band sie los. Abū Lubāba war einer von ihnen.","w":161},{"s":9,"a":107,"b":108,"g":"w","de":"Heuchler bauten neben Qubāʾ eine eigene Moschee, um die Gläubigen zu spalten, und baten den Propheten ﷺ, darin zu beten. Die Verse kamen: Stell dich niemals hinein. Eine Moschee, die vom ersten Tag an auf Gottesfurcht gegründet wurde, hat mehr Recht darauf.","w":162},{"s":9,"a":108,"b":108,"g":"w","de":"Der Vers lobt die Leute von Qubāʾ: Darin sind Männer, die sich gern reinigen. Der Prophet ﷺ fragte sie danach; sie erklärten, dass sie sich nach dem Gang zur Toilette mit Wasser reinigten.","src":"Abū Dāwūd 44, Tirmidhī 3100"},{"s":9,"a":113,"b":113,"g":"s","de":"Als Abū Ṭālib, der Onkel des Propheten ﷺ, im Sterben lag, bat ihn der Prophet: Sag Lā ilāha illallāh. Doch Abū Dschahl und ein anderer redeten auf ihn ein, und er starb auf der Religion seiner Väter. Der Prophet ﷺ sagte: Ich bitte für dich um Vergebung, solange es mir nicht verboten wird. Dann kam dieser Vers.","src":"Buchārī 1360, Muslim 24","w":163},{"s":9,"a":117,"b":119,"g":"s","de":"Kaʿb ibn Mālik und zwei andere waren ohne Entschuldigung vom Feldzug nach Tabūk ferngeblieben. Sie logen nicht, sondern gestanden ehrlich. Fünfzig Tage sprach niemand mit ihnen, bis die Erde ihnen eng wurde. Dann nahm Allah ihre Reue mit diesen Versen an – und Vers 119 sagt: Seid mit den Wahrhaftigen!","src":"Buchārī 4418, Muslim 2769"},{"s":9,"a":122,"b":122,"g":"w","de":"Als die Muslime hörten, wie die Heuchler getadelt wurden, wollten alle bei jedem Feldzug mitziehen. Der Vers sagt: Die Gläubigen sollen nicht alle ausziehen – eine Gruppe soll bleiben, um sich in der Religion Wissen anzueignen und die anderen zu lehren.","w":165},{"s":11,"a":5,"b":5,"g":"w","de":"Al-Akhnas ibn Scharīq sprach zum Propheten ﷺ freundlich, verbarg aber Feindschaft im Herzen. Der Vers sagt: Sie verhüllen ihre Brust, um sich vor Ihm zu verbergen – doch Allah weiß, was sie verbergen und was sie offenlegen.","w":185},{"s":11,"a":114,"b":114,"g":"s","de":"Ein Mann kam zum Propheten ﷺ und bekannte, dass er gegenüber einer Frau eine kleine Sünde begangen hatte, und bat um ein Urteil. Darauf kam der Vers: Verrichte das Gebet an beiden Enden des Tages – gute Taten löschen schlechte aus. Er fragte: Gilt das nur für mich? Der Prophet ﷺ sagte: Für alle aus meiner Gemeinschaft.","src":"Buchārī 526, Muslim 2763","w":184},{"s":13,"a":13,"b":13,"g":"w","de":"Ein hochmütiger Anführer spottete, als man ihn zum Propheten ﷺ rief: Was ist Allah – aus Gold, Silber oder Kupfer? Da schlug ein Blitz in ihn ein. Darauf kam der Vers: Er sendet die Blitze und trifft damit, wen Er will.","src":"Nasāʾī al-Kubrā – Anas","w":186},{"s":13,"a":30,"b":30,"g":"w","de":"Beim Vertrag von Ḥudaibiya sollte ʿAlī „Bismillāhi r-Raḥmāni r-Raḥīm“ schreiben. Die Quraisch sagten: Wir kennen keinen „ar-Raḥmān“. Der Vers sagt: Sie verleugnen den Allerbarmer. Sag: Er ist mein Herr – es gibt keinen Gott außer Ihm.","w":187},{"s":13,"a":31,"b":31,"g":"w","de":"Die Quraisch forderten: Lass die Berge weichen, Flüsse fließen und unsere Toten sprechen, wenn du ein Prophet bist! Der Prophet ﷺ wählte stattdessen das Tor der Barmherzigkeit, damit Menschen noch glauben können. Darauf kam: Selbst wenn ein Qur'an Berge versetzte …","w":188},{"s":13,"a":38,"b":38,"g":"w","de":"Einige spotteten, ein echter Prophet würde nicht heiraten und Familie haben. Der Vers antwortet: Wir haben schon vor dir Gesandte geschickt und ihnen Frauen und Kinder gegeben.","w":189},{"s":15,"a":47,"b":47,"g":"w","de":"Nach ʿAlī ibn al-Ḥusain bezieht sich der Vers auch auf Abū Bakr, ʿUmar und ʿAlī: Vor dem Islam gab es Feindschaft zwischen ihren Stämmen, im Islam liebten sie sich. Im Paradies nimmt Allah allen Groll aus den Herzen – sie sitzen als Brüder einander gegenüber.","w":190},{"s":15,"a":49,"b":50,"g":"w","de":"Der Prophet ﷺ sah Gefährten laut lachen und ermahnte sie. Dann kam Dschibrīl: Allah sagt, warum bringst du Meine Diener zur Verzweiflung? Verkünde Meinen Dienern, dass Ich der Allvergebende, der Barmherzige bin – und dass Meine Strafe schmerzhaft ist.","w":191},{"s":15,"a":87,"b":88,"g":"w","de":"Reiche Karawanen kamen in Medina an, und arme Muslime wünschten sich solchen Reichtum. Der Vers sagt: Wir haben dir die sieben oft wiederholten Verse (al-Fātiḥa) und den gewaltigen Qur'an gegeben – richte deine Augen nicht auf den Besitz anderer.","w":192},{"s":16,"a":4,"b":4,"g":"w","de":"Ubayy ibn Khalaf brachte zerfallene Knochen zum Propheten ﷺ, zerrieb sie und fragte: Soll Allah das wieder lebendig machen? Darauf beziehen sich dieser Vers und das Ende von Sure Yā-Sīn: Er hat den Menschen aus einem Tropfen erschaffen – und doch ist er ein offenkundiger Widersacher.","w":198},{"s":16,"a":38,"b":38,"g":"w","de":"Ein Muslim forderte von einem Götzendiener eine Schuld zurück und sagte dabei: bei dem, auf den ich nach dem Tod hoffe. Der andere schwor: Allah wird niemanden auferwecken, der stirbt. Der Vers antwortet: Doch – ein wahres Versprechen Allahs.","w":197},{"s":16,"a":75,"b":76,"g":"w","de":"Die beiden Gleichnisse vom Mann, der nichts hat, und dem, der frei spendet, sowie vom Stummen und dem, der zur Gerechtigkeit aufruft, wurden nach einer Überlieferung auf ʿUthmān ibn ʿAffān und andere bezogen. Sie zeigen: Wer Gutes tut und gerecht ist, ist nicht gleich mit dem, der nichts nützt.","w":199},{"s":16,"a":101,"b":102,"g":"w","de":"Die Götzendiener sagten: Muhammad befiehlt heute etwas und morgen etwas anderes – er erfindet das. Die Verse antworten: Wenn Allah einen Vers durch einen anderen ersetzt, weiß Er am besten, was Er herabsendet; der Heilige Geist bringt ihn mit der Wahrheit.","w":193},{"s":16,"a":103,"b":103,"g":"w","de":"Der Prophet ﷺ hörte manchmal zwei christlichen Schwertschmieden in Mekka zu, die ihre Schrift lasen. Die Götzendiener behaupteten: Die bringen ihm den Qur'an bei! Der Vers antwortet: Die Sprache dessen, auf den sie anspielen, ist fremd – dies aber ist klares Arabisch.","w":194},{"s":16,"a":106,"b":106,"g":"w","de":"Die Götzendiener folterten ʿAmmār ibn Yāsir und seine Eltern; seine Mutter Sumayya und sein Vater starben dabei als erste Märtyrer. ʿAmmār sagte unter Zwang, was sie hören wollten, und kam weinend zum Propheten ﷺ. Der Vers sagt: Wer gezwungen wird, während sein Herz fest im Glauben ruht, trägt keine Schuld.","w":195},{"s":16,"a":125,"b":127,"g":"w","de":"Nach Uḥud sah der Prophet ﷺ, was man seinem Onkel Ḥamza angetan hatte, und war tief erschüttert; er wollte Vergeltung üben. Darauf kamen die Verse: Ruf auf mit Weisheit und schöner Ermahnung … und wenn ihr geduldig seid, ist das besser für die Geduldigen. Er wählte die Geduld.","w":196},{"s":17,"a":29,"b":29,"g":"w","de":"Eine Frau ließ den Propheten ﷺ um ein Gewand bitten; als er keins hatte, gab er sein eigenes weg und konnte so nicht zum Gebet hinausgehen. Der Vers lehrt das rechte Maß: Halte deine Hand nicht an den Hals gefesselt, öffne sie aber auch nicht ganz.","w":201},{"s":17,"a":59,"b":59,"g":"w","de":"Die Mekkaner forderten, den Hügel Ṣafā in Gold zu verwandeln. Allah ließ dem Propheten ﷺ die Wahl: das Wunder – mit Strafe, wenn sie dann nicht glauben – oder Geduld mit ihnen. Er wählte die Geduld. Der Vers: Nichts hinderte Uns, Zeichen zu senden, außer dass die Früheren sie geleugnet hatten.","src":"Aḥmad 2333 – Ibn ʿAbbās","w":202},{"s":17,"a":60,"b":60,"g":"w","de":"Als der Baum Zaqqūm in der Hölle erwähnt wurde, spottete Abū Dschahl: Zaqqūm, das ist doch Datteln mit Butter – her damit! Der Vers sagt: Den verfluchten Baum im Qur'an haben Wir nur zur Prüfung gemacht – doch es mehrt bei ihnen nur die Widerspenstigkeit.","w":203},{"s":17,"a":73,"b":75,"g":"w","de":"Eine Abordnung von Thaqīf stellte Bedingungen für den Islam, etwa, ihren Götzen noch ein Jahr verehren zu dürfen. Der Prophet ﷺ lehnte ab. Die Verse sagen: Fast hätten sie dich von dem abgebracht, was Wir dir offenbart haben – hätten Wir dich nicht gefestigt.","w":204},{"s":17,"a":76,"b":76,"g":"w","de":"Einige sagten zum Propheten ﷺ: Die Propheten kamen alle in Syrien; wenn du einer bist, geh dorthin. Der Vers spricht davon, dass sie ihn aus dem Land treiben wollten – doch dann wären sie selbst nur kurz geblieben.","w":205},{"s":17,"a":80,"b":80,"g":"w","de":"Als die Quraisch den Propheten ﷺ festhalten oder vertreiben wollten, befahl Allah ihm die Auswanderung nach Medina und lehrte ihn das Gebet: Mein Herr, lass mich wahrhaftig eintreten und wahrhaftig hinausgehen, und gib mir von Dir eine helfende Macht.","w":206},{"s":17,"a":85,"b":85,"g":"s","de":"Einige jüdische Männer fragten den Propheten ﷺ in Medina: Was ist der Geist (ar-Rūḥ)? Er schwieg, bis die Offenbarung kam: Sie fragen dich nach dem Geist. Sag: Der Geist gehört zum Befehl meines Herrn, und euch ist vom Wissen nur wenig gegeben.","src":"Buchārī 125, Muslim 2794 – Ibn Masʿūd"},{"s":17,"a":90,"b":93,"g":"w","de":"Die Führer der Quraisch versammelten sich an der Kaaba und forderten Wunder: eine Quelle in Mekka, Gärten mit Flüssen, ein Haus aus Gold, einen Aufstieg in den Himmel. Der Prophet ﷺ antwortete, wie der Vers es lehrt: Gepriesen sei mein Herr – bin ich denn mehr als ein Mensch und Gesandter?","w":207},{"s":17,"a":110,"b":110,"g":"w","de":"Der Prophet ﷺ rief im Nachtgebet: Yā Raḥmān, yā Raḥīm! Die Götzendiener sagten: Er verbietet uns, zwei Götter anzurufen, und ruft selbst zwei an! Der Vers antwortet: Ruft Allah an oder ruft den Allerbarmer an – Ihm gehören die schönsten Namen.","w":200},{"s":17,"a":110,"b":110,"g":"s","de":"In Mekka betete der Prophet ﷺ laut vor; wenn die Götzendiener es hörten, beschimpften sie den Qur'an. Der Vers kam: Sei in deinem Gebet nicht zu laut und nicht zu leise, sondern suche einen Weg dazwischen.","src":"Buchārī 4722, Muslim 446 – Ibn ʿAbbās"},{"s":18,"a":28,"b":28,"g":"w","de":"Vornehme Stammesführer sagten zum Propheten ﷺ: Schick die Armen wie Salmān und Abū Dharr mit ihren Wollmänteln weg, dann setzen wir uns zu dir. Der Vers sagt: Halte dich geduldig zu denen, die morgens und abends ihren Herrn anrufen – wende deine Augen nicht von ihnen ab.","src":"Vgl. Muslim 2413 zu 6:52","w":209},{"s":18,"a":83,"b":83,"g":"w","de":"Leute fragten den Propheten ﷺ nach Dhu-l-Qarnain, um ihn zu prüfen. Darauf kamen die Verse, die von seinen Reisen und dem Damm gegen Yādschūdsch und Mādschūdsch erzählen.","w":210},{"s":18,"a":109,"b":109,"g":"w","de":"Als es hieß, den Menschen sei nur wenig Wissen gegeben, sagten einige: Wir haben die Tora – das ist viel Gutes! Der Vers antwortet: Wäre das Meer Tinte für die Worte meines Herrn, so wäre das Meer erschöpft, bevor die Worte meines Herrn erschöpft wären.","w":208},{"s":19,"a":64,"b":64,"g":"s","de":"Der Prophet ﷺ fragte Dschibrīl: Was hindert dich, uns öfter zu besuchen? Darauf kam: Wir kommen nur auf Befehl deines Herrn herab – Ihm gehört, was vor uns und was hinter uns ist; und dein Herr ist niemals vergesslich.","src":"Buchārī 4731 – Ibn ʿAbbās","w":212},{"s":19,"a":66,"b":67,"g":"w","de":"Ubayy ibn Khalaf hielt zerfallene Knochen in der Hand und spottete über die Auferstehung. Der Vers antwortet: Erinnert sich der Mensch nicht, dass Wir ihn erschaffen haben, als er nichts war?","w":213},{"s":19,"a":77,"b":80,"g":"s","de":"Khabbāb ibn al-Aratt, ein Schmied, forderte von al-ʿĀṣ ibn Wāʾil seinen Lohn. Der sagte: Ich zahle erst, wenn du Muhammad verleugnest. Khabbāb: Niemals – nicht einmal, wenn du stirbst und auferweckt wirst. Al-ʿĀṣ spottete: Dann bezahle ich dich dort mit meinem Besitz und meinen Kindern. Darauf kamen diese Verse.","src":"Buchārī 4732, Muslim 2795","w":214},{"s":20,"a":1,"b":2,"g":"w","de":"Der Prophet ﷺ betete und stand nachts so lange, dass die Gegner sagten: Dieser Qur'an macht ihn nur unglücklich. Allah antwortete: Ṭā-Hā. Wir haben dir den Qur'an nicht herabgesandt, damit du unglücklich wirst.","w":215},{"s":22,"a":11,"b":11,"g":"w","de":"Manche Beduinen nahmen den Islam an und waren zufrieden, solange es ihnen gut ging. Kam aber Krankheit oder Verlust, sagten sie: Diese Religion bringt nur Unglück – und wandten sich ab. Der Vers beschreibt sie: Manche dienen Allah wie am Rand – trifft sie Gutes, sind sie beruhigt, trifft sie eine Prüfung, kehren sie um.","src":"Buchārī 4742 – Ibn ʿAbbās","w":216},{"s":22,"a":19,"b":19,"g":"s","de":"Abū Dharr schwor, dass dieser Vers über die sechs Männer bei Badr herabkam, die vor der Schlacht zum Zweikampf antraten: Ḥamza, ʿUbaida und ʿAlī gegen ʿUtba, Schaiba und al-Walīd. Diese beiden Streitparteien streiten um ihren Herrn.","src":"Buchārī 4743, Muslim 3033","w":217},{"s":22,"a":39,"b":40,"g":"w","de":"In Mekka wurden die Gefährten geschlagen und verletzt, doch der Prophet ﷺ sagte: Seid geduldig, mir ist der Kampf nicht befohlen. Nach der Auswanderung kam dieser Vers als erste Erlaubnis zum Kampf: Erlaubnis ist denen gegeben, die bekämpft werden, weil ihnen Unrecht geschah.","src":"Tirmidhī 3171 – Ibn ʿAbbās","w":218},{"s":23,"a":1,"b":10,"g":"w","de":"ʿUmar berichtete: Als Offenbarung kam, hörte man ein Summen wie von Bienen. Dann betete der Prophet ﷺ und sagte: Mir wurden zehn Verse offenbart – wer sie befolgt, kommt ins Paradies. Dann las er: Erfolgreich sind die Gläubigen … bis Vers 10.","src":"Tirmidhī 3173","w":220},{"s":23,"a":14,"b":14,"g":"w","de":"ʿUmar sagte: In mehreren Dingen stimmte meine Meinung mit dem Qur'an überein. Als die Verse über die Erschaffung des Menschen im Mutterleib kamen, rief er: Segensreich ist Allah, der beste Schöpfer! – und genau so endet der Vers.","w":221},{"s":23,"a":76,"b":76,"g":"w","de":"Mekka litt unter einer Hungersnot, sodass die Menschen sogar Tierhaare aßen. Abū Sufyān kam zum Propheten ﷺ und bat bei der Verwandtschaft um Hilfe. Der Vers sagt: Wir haben sie mit Strafe gepackt, doch sie demütigten sich nicht vor ihrem Herrn.","w":223},{"s":24,"a":11,"b":20,"g":"s","de":"Heuchler verbreiteten eine böse Lüge über ʿĀʾischa, die Mutter der Gläubigen. Einen Monat litt sie darunter, bis Allah ihre Unschuld mit diesen Versen offenbarte. Vers 16 lobt, was Abū Ayyūb und seine Frau sagten, als sie davon hörten: Es steht uns nicht zu, darüber zu reden – gepriesen seist Du, das ist eine gewaltige Verleumdung!","src":"Buchārī 4750, Muslim 2770","w":224},{"s":24,"a":22,"b":22,"g":"s","de":"Abū Bakr unterstützte seinen armen Verwandten Misṭaḥ. Als dieser sich an der Verleumdung gegen ʿĀʾischa beteiligte, schwor Abū Bakr, ihm nichts mehr zu geben. Der Vers kam: Sie sollen verzeihen und nachsichtig sein – liebt ihr es nicht, dass Allah euch vergibt? Abū Bakr sagte: Doch, ich liebe es! – und half ihm wieder.","src":"Buchārī 4750"},{"s":24,"a":27,"b":29,"g":"w","de":"Eine Frau aus Medina sagte: Manchmal bin ich zu Hause in einem Zustand, in dem mich niemand sehen soll – und dann kommt jemand herein. Darauf kam: Betretet keine fremden Häuser, bevor ihr um Erlaubnis gebeten und die Bewohner gegrüßt habt. Abū Bakr fragte nach unbewohnten Rasthäusern – dafür kam die Erleichterung in Vers 29.","w":225},{"s":24,"a":33,"b":33,"g":"w","de":"Ein Sklave namens Ṣubaiḥ bat seinen Herrn um einen Freikaufvertrag, doch der weigerte sich. Der Vers befahl: Wenn eure Sklaven einen Freikaufvertrag wünschen, schließt ihn mit ihnen ab, wenn ihr Gutes in ihnen wisst – und gebt ihnen von Allahs Vermögen.","w":227},{"s":24,"a":48,"b":50,"g":"w","de":"Ein Heuchler hatte Streit mit einem Juden um ein Stück Land. Der Jude wollte zum Propheten ﷺ gehen, der Heuchler lieber zu jemand anderem, weil er fürchtete, beim Propheten zu verlieren. Die Verse tadeln: Wenn sie zu Allah und Seinem Gesandten gerufen werden, wendet sich ein Teil von ihnen ab.","w":228},{"s":24,"a":58,"b":58,"g":"w","de":"Ein Junge wurde mittags zu ʿUmar geschickt und trat ein, als ʿUmar sich ausruhte und nicht gesehen werden wollte. ʿUmar wünschte sich eine Regel – und der Vers kam: Kinder und Bedienstete sollen zu drei Zeiten um Erlaubnis bitten: vor dem Fadschr, zur Mittagsruhe und nach dem ʿIschāʾ.","w":229},{"s":24,"a":61,"b":61,"g":"w","de":"Nach einem Vers gegen unrechtmäßiges Verzehren von Vermögen scheuten sich manche, mit Blinden, Lahmen und Kranken zu essen – aus Angst, ihnen unbewusst etwas wegzunehmen. Umgekehrt fühlten sich diese bei Gesunden unwohl. Der Vers erlaubt: Es gibt keinen Vorwurf für den Blinden, den Lahmen und den Kranken – esst gemeinsam oder getrennt.","w":231},{"s":25,"a":27,"b":29,"g":"w","de":"ʿUqba ibn Abī Muʿaiṭ hatte den Propheten ﷺ zum Essen eingeladen und das Glaubensbekenntnis gesprochen. Sein Freund Ubayy ibn Khalaf drängte ihn, das zu widerrufen – und er tat es. Die Verse beschreiben den Tag, an dem der Ungerechte sich in die Hände beißt: Hätte ich doch den Weg mit dem Gesandten gewählt und nicht jenen zum Freund genommen!","w":233},{"s":25,"a":68,"b":70,"g":"s","de":"Einige Götzendiener, die schwere Sünden begangen hatten, sagten: Was du lehrst, ist gut – aber gibt es für uns noch Vergebung? Darauf kamen die Verse: … außer wer bereut, glaubt und Gutes tut – deren schlechte Taten wandelt Allah in gute um.","src":"Buchārī 4810, Muslim 122 – Ibn ʿAbbās","w":234},{"s":26,"a":214,"b":214,"g":"s","de":"Als der Vers kam „Und warne deine nächsten Verwandten“, stieg der Prophet ﷺ auf den Hügel Ṣafā und rief die Stämme der Quraisch zusammen: Würdet ihr mir glauben, wenn ich sage, ein Heer steht hinter diesem Berg? – Ja, du hast nie gelogen. – So warne ich euch vor einer schweren Strafe.","src":"Buchārī 4770, Muslim 208"},{"s":28,"a":56,"b":56,"g":"s","de":"Der Prophet ﷺ wünschte sich sehr, dass sein Onkel Abū Ṭālib vor dem Tod glaubt, doch er starb ohne das Glaubensbekenntnis. Der Vers tröstet: Du kannst nicht rechtleiten, wen du liebst – Allah leitet recht, wen Er will.","src":"Muslim 25, Buchārī 4772"},{"s":28,"a":57,"b":57,"g":"w","de":"Ein Mann aus Mekka sagte: Wir wissen, dass du die Wahrheit sagst – aber wenn wir dir folgen, vertreiben uns die Araber aus unserem Land. Der Vers antwortet: Haben Wir ihnen nicht einen sicheren heiligen Bezirk gegeben, zu dem Früchte aller Art gebracht werden?","w":235},{"s":28,"a":61,"b":61,"g":"w","de":"Nach Mudschāhid geht es um ʿAlī und Ḥamza auf der einen und Abū Dschahl auf der anderen Seite: Ist der, dem Allah ein schönes Versprechen gegeben hat, gleich dem, dem Er nur den Genuss dieses Lebens gab?","w":236},{"s":28,"a":68,"b":68,"g":"w","de":"Al-Walīd ibn al-Mughīra fragte, warum der Qur'an nicht einem bedeutenden Mann aus Mekka oder Ṭāʾif herabgesandt wurde. Der Vers antwortet: Dein Herr erschafft, was Er will, und wählt aus – sie haben keine Wahl.","w":237},{"s":29,"a":1,"b":3,"g":"w","de":"Einige Muslime in Mekka wollten nach Medina auswandern, wurden aber von den Götzendienern verfolgt und gequält. Über sie kamen die Verse: Meinen die Menschen, man ließe sie in Ruhe, weil sie sagen „Wir glauben“, ohne dass sie geprüft werden?","w":238},{"s":29,"a":8,"b":8,"g":"s","de":"Als Saʿd ibn Abī Waqqāṣ Muslim wurde, schwor seine Mutter, nicht zu essen und nicht zu trinken, bis er den Islam verlässt. Saʿd blieb standhaft, aber freundlich zu ihr. Der Vers kam: Wir haben dem Menschen Güte gegen seine Eltern geboten – wenn sie dich aber drängen, Mir etwas beizugesellen, gehorche ihnen darin nicht.","src":"Muslim 1748","w":241},{"s":29,"a":10,"b":10,"g":"w","de":"Der Vers spricht von Menschen, die mit der Zunge sagen „Wir glauben“, aber bei der ersten Prüfung die Verfolgung durch Menschen fürchten, als wäre sie Allahs Strafe.","w":239},{"s":30,"a":1,"b":5,"g":"w","de":"Die Perser besiegten die Römer (Byzanz). Die Götzendiener in Mekka freuten sich, die Muslime waren traurig, denn die Römer hatten eine Schrift. Die Verse sagten voraus: Die Römer werden in wenigen Jahren siegen. Abū Bakr wettete darauf – und es geschah, wie Allah es angekündigt hatte.","src":"Tirmidhī 3193","w":242},{"s":31,"a":6,"b":6,"g":"w","de":"An-Naḍr ibn al-Ḥārith brachte Geschichten persischer Könige aus dem Ausland mit und erzählte sie in Mekka, um die Leute vom Qur'an abzulenken. Der Vers tadelt, wer „unterhaltsames Gerede“ kauft, um von Allahs Weg abzubringen.","w":245},{"s":31,"a":15,"b":15,"g":"w","de":"Auch dieser Vers betrifft Saʿd ibn Abī Waqqāṣ und seine Mutter. Der Satz „folge dem Weg dessen, der sich Mir zuwendet“ meint nach Ibn ʿAbbās Abū Bakr – durch ihn nahmen ʿUthmān, ʿAbd ar-Raḥmān ibn ʿAuf, Saʿd und andere den Islam an.","w":243},{"s":31,"a":27,"b":27,"g":"w","de":"Einige Gelehrte sagten: Wir haben die Tora erhalten, wie kann unser Wissen gering sein? Der Vers antwortet: Wären alle Bäume Schreibrohre und das Meer Tinte, mit sieben weiteren Meeren – die Worte Allahs würden nicht zu Ende gehen.","w":244},{"s":32,"a":16,"b":16,"g":"w","de":"Der Vers lobt die, die nachts ihr Bett verlassen, um ihren Herrn in Furcht und Hoffnung anzurufen. Anas sagte, er wurde über die Anṣār offenbart, die zwischen Maghrib und ʿIschāʾ in der Moschee beteten; andere beziehen ihn auf das Nachtgebet.","src":"Tirmidhī 3196","w":246},{"s":32,"a":18,"b":20,"g":"w","de":"Al-Walīd ibn ʿUqba prahlte vor ʿAlī: Ich bin stärker, beredter und besser als du. ʿAlī antwortete: Schweig! Darauf kam: Ist denn der Gläubige wie der Frevler? Sie sind nicht gleich.","w":247},{"s":33,"a":1,"b":3,"g":"w","de":"Nach Uḥud kamen Anführer der Mekkaner nach Medina und forderten vom Propheten ﷺ: Sag, dass unsere Götzen Fürsprache einlegen können, dann lassen wir dich in Ruhe. Die Verse kamen: O Prophet, fürchte Allah und gehorche nicht den Ungläubigen und Heuchlern – vertraue auf Allah.","w":248},{"s":33,"a":4,"b":5,"g":"w","de":"Die Quraisch sagten über einen klugen Mann, er habe zwei Herzen. Außerdem nannten sie Zaid ibn Ḥāritha „Zaid ibn Muhammad“, weil der Prophet ﷺ ihn adoptiert hatte. Die Verse stellen klar: Allah hat keinem Menschen zwei Herzen gegeben – und nennt Adoptivkinder nach ihren leiblichen Vätern.","src":"Buchārī 4782","w":250},{"s":33,"a":23,"b":23,"g":"s","de":"Anas ibn an-Naḍr hatte Badr verpasst und schwor: Wenn Allah mich einen Kampf erleben lässt, wird Er sehen, was ich tue. Bei Uḥud kämpfte er tapfer und rief: Ich rieche den Duft des Paradieses! Er fiel als Märtyrer. Über ihn und seinesgleichen kam der Vers: Unter den Gläubigen sind Männer, die ihr Versprechen gegenüber Allah gehalten haben.","src":"Buchārī 2805, Muslim 1903","w":249},{"s":33,"a":35,"b":35,"g":"w","de":"Umm Salama fragte: Warum werden im Qur'an die Männer erwähnt und die Frauen nicht? Darauf kam der Vers, der gläubige Männer und Frauen gemeinsam nennt: die muslimischen Männer und Frauen, die gläubigen Männer und Frauen …","src":"Aḥmad 26575, Nasāʾī al-Kubrā"},{"s":33,"a":43,"b":43,"g":"w","de":"Als der Vers kam, dass Allah und Seine Engel den Propheten segnen, sagte Abū Bakr: Allah hat dir nichts Gutes gegeben, ohne uns daran teilhaben zu lassen. Darauf kam: Er ist es, der euch segnet, und Seine Engel, um euch aus den Finsternissen ins Licht zu bringen.","w":251},{"s":33,"a":53,"b":53,"g":"s","de":"Bei der Hochzeitsfeier des Propheten ﷺ mit Zainab bint Dschaḥsch blieben nach dem Essen einige Gäste lange sitzen, und der Prophet ﷺ war zu schüchtern, sie zu bitten zu gehen. Der Vers kam mit Regeln: Betretet die Häuser des Propheten nicht unaufgefordert, und wenn ihr gegessen habt, geht auseinander.","src":"Buchārī 4793, Muslim 1428 – Anas","w":253},{"s":33,"a":56,"b":56,"g":"s","de":"Die Gefährten sagten: Wir wissen, wie wir dich grüßen, aber wie sprechen wir den Segen über dich? Der Prophet ﷺ lehrte sie: Allāhumma ṣalli ʿalā Muḥammad … (Buchārī 4797). Der Vers: Allah und Seine Engel segnen den Propheten – o ihr Gläubigen, sprecht Segen über ihn und grüßt ihn mit gebührendem Gruß.","w":254},{"s":36,"a":12,"b":12,"g":"w","de":"Der Stamm Banū Salima wohnte weit von der Moschee und wollte näher heranziehen. Der Prophet ﷺ sagte: Bleibt, eure Schritte werden aufgeschrieben! Dazu kam der Vers: Wir schreiben auf, was sie vorausgeschickt haben, und ihre Spuren.","src":"Tirmidhī 3226; vgl. Muslim 665","w":256},{"s":36,"a":77,"b":79,"g":"w","de":"Ubayy ibn Khalaf kam mit einem zerfallenen Knochen, zerrieb ihn und fragte: Wer macht diese Knochen wieder lebendig? Der Vers antwortet: Lebendig macht sie Der, der sie das erste Mal erschaffen hat – Er weiß über jede Schöpfung Bescheid.","w":257},{"s":38,"a":5,"b":11,"g":"w","de":"Als Abū Ṭālib krank war, beschwerten sich die Quraisch über den Propheten ﷺ. Er sagte: Ich will von ihnen nur ein Wort, durch das alle Araber ihnen folgen: Lā ilāha illallāh. Sie riefen: Macht er die Götter zu einem einzigen Gott? Das ist wirklich seltsam! Darauf kamen diese Verse.","src":"Tirmidhī 3232","w":258},{"s":39,"a":17,"b":18,"g":"w","de":"Nach Ibn Zaid geht es um Menschen, die schon vor dem Islam den Götzendienst mieden, wie Zaid ibn ʿAmr, Abū Dharr und Salmān. Nach Ibn ʿAbbās auch um ʿUthmān, ʿAbd ar-Raḥmān, Ṭalḥa, az-Zubair und andere, die durch Abū Bakr glaubten: Verkünde frohe Botschaft Meinen Dienern, die auf das Wort hören und dem Besten davon folgen.","w":259},{"s":39,"a":23,"b":23,"g":"w","de":"Die Gefährten baten: O Gesandter Allahs, erzähl uns doch etwas! Darauf kam der Vers: Allah hat die schönste Rede herabgesandt – ein Buch, dessen Teile einander ähneln und wiederholt werden; davon erschauern die Haut derer, die ihren Herrn fürchten.","w":260},{"s":39,"a":53,"b":53,"g":"s","de":"Einige, die viele schwere Sünden begangen hatten, fragten, ob es für sie noch Vergebung gebe. Darauf kam: Sag: O Meine Diener, die ihr maßlos gegen euch selbst wart, verzweifelt nicht an Allahs Barmherzigkeit – Allah vergibt alle Sünden.","src":"Buchārī 4810 – Ibn ʿAbbās"},{"s":39,"a":67,"b":67,"g":"s","de":"Ein Gelehrter der Schriftbesitzer erzählte dem Propheten ﷺ, Allah werde am Tag der Auferstehung die Himmel und die Erde auf Seinen Fingern halten. Der Prophet ﷺ lachte zustimmend und las den Vers: Sie haben Allah nicht so geschätzt, wie Ihm gebührt – die ganze Erde wird am Tag der Auferstehung in Seiner Hand sein.","src":"Buchārī 4811, Muslim 2786","w":261},{"s":41,"a":22,"b":23,"g":"s","de":"Drei Männer saßen an der Kaaba und fragten sich: Hört Allah, was wir sagen? Einer meinte: Wenn wir laut reden, hört Er; leise nicht. Ein anderer: Wenn Er etwas hört, hört Er alles. Der Vers kam: Ihr habt euch nicht davor verborgen, dass eure Ohren, Augen und Haut gegen euch zeugen würden.","src":"Buchārī 4817, Muslim 2775 – Ibn Masʿūd","w":262},{"s":42,"a":23,"b":23,"g":"w","de":"Die Anṣār wollten dem Propheten ﷺ in Medina Geld zusammentragen, weil er wenig besaß. Der Vers kam: Sag: Ich verlange von euch keinen Lohn dafür, außer der Liebe zu den Verwandten.","w":263},{"s":42,"a":27,"b":27,"g":"w","de":"Arme Gefährten, die in der Moschee wohnten (Ahl aṣ-Ṣuffa), wünschten sich den Reichtum anderer Stämme. Der Vers sagt: Würde Allah allen Seinen Dienern die Versorgung weit machen, würden sie auf der Erde übermütig – darum sendet Er sie nach Maß.","w":264},{"s":42,"a":51,"b":51,"g":"w","de":"Einige verlangten: Sprich mit Allah und sieh Ihn an wie Mūsā, sonst glauben wir dir nicht. Der Prophet ﷺ sagte: Auch Mūsā hat Allah nicht gesehen. Der Vers erklärt: Allah spricht zu einem Menschen nur durch Eingebung, hinter einem Vorhang oder durch einen Engel als Boten.","w":265},{"s":43,"a":57,"b":59,"g":"w","de":"Der Prophet ﷺ sagte: Es ist nichts Gutes an dem, was neben Allah angebetet wird. Die Quraisch erwiderten: Aber ʿĪsā wird doch auch angebetet – und du nennst ihn einen Propheten! Die Verse antworten: Er war nur ein Diener, dem Wir Gnade erwiesen haben.","w":266},{"s":44,"a":49,"b":49,"g":"w","de":"Abū Dschahl prahlte: Ich bin der Mächtigste und Edelste zwischen den Bergen Mekkas! Der Vers spricht von seinem Ende: Koste! Du warst ja der Mächtige, der Edle!","w":267},{"s":45,"a":14,"b":14,"g":"w","de":"Auf einem Feldzug spottete ʿAbdullāh ibn Ubayy über die Muslime. ʿUmar wollte ihn dafür bestrafen. Der Vers kam: Sag den Gläubigen, sie sollen denen vergeben, die nicht auf die Tage Allahs hoffen.","w":268},{"s":46,"a":9,"b":9,"g":"w","de":"Als die Verfolgung in Mekka schlimmer wurde, sah der Prophet ﷺ im Traum ein Land mit Palmen und Wasser. Die Gefährten fragten: Wann wandern wir aus? Der Vers: Sag: Ich weiß nicht, was mit mir und euch geschehen wird – ich folge nur dem, was mir offenbart wird.","w":270},{"s":48,"a":1,"b":5,"g":"s","de":"Nach Ḥudaibiya waren die Gefährten traurig, weil sie nicht zur ʿUmra durften. Da kam: Wir haben dir einen offenkundigen Sieg geschenkt. Sie sagten: Glückwunsch, o Gesandter Allahs – aber was ist für uns? Darauf kam Vers 5: damit Er die gläubigen Männer und Frauen in Gärten eingehen lässt.","src":"Buchārī 4172 – Anas","w":272},{"s":48,"a":24,"b":24,"g":"s","de":"Bei Ḥudaibiya kamen achtzig bewaffnete Männer aus Mekka, um die Muslime zu überfallen. Sie wurden gefangen genommen, doch der Prophet ﷺ ließ sie frei. Darauf kam: Er ist es, der ihre Hände von euch und eure Hände von ihnen im Tal von Mekka zurückhielt.","src":"Muslim 1808 – Anas","w":271},{"s":49,"a":1,"b":1,"g":"s","de":"Eine Abordnung der Banū Tamīm kam. Abū Bakr schlug einen Anführer für sie vor, ʿUmar einen anderen, und sie stritten mit lauten Stimmen vor dem Propheten ﷺ. Darauf kamen die ersten Verse von al-Ḥudschurāt: Kommt Allah und Seinem Gesandten nicht zuvor.","src":"Buchārī 4847","w":273},{"s":49,"a":2,"b":3,"g":"s","de":"Thābit ibn Qais hatte eine laute Stimme. Als der Vers kam „Erhebt eure Stimmen nicht über die Stimme des Propheten“, blieb er traurig zu Hause und dachte, seine Taten seien verloren. Der Prophet ﷺ ließ ihm sagen: Du gehörst zu den Leuten des Paradieses. Abū Bakr sprach danach nur noch leise mit dem Propheten.","src":"Buchārī 3613, Muslim 119","w":277},{"s":49,"a":4,"b":5,"g":"w","de":"Leute aus den Banū Tamīm riefen laut vor den Wohnräumen des Propheten ﷺ: O Muhammad, komm heraus! Der Vers sagt: Die meisten derer, die dich von draußen rufen, haben keinen Verstand – hätten sie gewartet, bis du herauskommst, wäre es besser für sie gewesen.","w":279},{"s":49,"a":6,"b":8,"g":"w","de":"Al-Walīd ibn ʿUqba sollte bei den Banū l-Muṣṭaliq die Zakāh einsammeln. Aus Angst kehrte er unterwegs um und behauptete, sie wollten ihn töten. Fast wäre es zum Kampf gekommen, doch der Stamm kam selbst und klärte alles auf. Der Vers lehrt: Wenn euch ein Unzuverlässiger eine Nachricht bringt, prüft sie genau.","src":"Aḥmad 18459","w":280},{"s":49,"a":9,"b":9,"g":"s","de":"Als der Prophet ﷺ zu ʿAbdullāh ibn Ubayy ritt, beleidigte dieser ihn. Ein Gefährte verteidigte den Propheten, und zwischen beiden Gruppen kam es zu einem Handgemenge mit Palmzweigen und Sandalen. Dazu kam: Wenn zwei Gruppen von Gläubigen kämpfen, stiftet Frieden zwischen ihnen.","src":"Buchārī 2691, Muslim 1799 – Anas","w":281},{"s":49,"a":11,"b":11,"g":"w","de":"Thābit ibn Qais drängte sich durch die Reihen, um nahe beim Propheten ﷺ zu sitzen, und verspottete einen Mann wegen dessen Mutter. Der Mann senkte beschämt den Kopf. Der Vers kam: Keine Leute sollen über andere spotten, vielleicht sind diese besser als sie – und gebt euch keine Schimpfnamen.","w":274},{"s":49,"a":13,"b":13,"g":"w","de":"Am Tag der Befreiung Mekkas rief Bilāl auf der Kaaba den Adhān. Einige spotteten über seine Herkunft und Hautfarbe. Der Vers kam: O ihr Menschen, Wir haben euch aus Mann und Frau erschaffen und zu Völkern und Stämmen gemacht, damit ihr einander kennenlernt – der Edelste bei Allah ist der Gottesfürchtigste.","w":275},{"s":49,"a":14,"b":14,"g":"w","de":"Beduinen kamen in einem Dürrejahr nach Medina, sagten „Wir glauben“ und verlangten Gaben, als hätten sie dem Propheten ﷺ einen Gefallen getan. Der Vers sagt: Sagt nicht „Wir glauben“, sondern „Wir haben uns ergeben“ – der Glaube ist noch nicht in eure Herzen eingezogen.","w":276},{"s":53,"a":32,"b":32,"g":"w","de":"Der Vers sagt: Allah kennt euch am besten – seit Er euch aus der Erde erschuf und als ihr verborgen im Leib eurer Mütter wart. Darum erklärt euch nicht selbst für rein.","w":283},{"s":53,"a":33,"b":37,"g":"w","de":"Nach einer Überlieferung spendete ʿUthmān viel. Jemand sagte: Du hast bald nichts mehr – gib mir etwas, und ich trage deine Sünden für dich. ʿUthmān gab ein wenig und hielt dann seine Spenden zurück. Die Verse sagen: Niemand trägt die Last eines anderen – da spendete ʿUthmān wieder wie zuvor.","w":284},{"s":53,"a":43,"b":43,"g":"w","de":"Der Prophet ﷺ sah lachende Leute und sagte: Wüsstet ihr, was ich weiß, würdet ihr wenig lachen und viel weinen. Bald darauf kam Dschibrīl mit dem Vers: Er ist es, der lachen und weinen lässt.","w":285},{"s":54,"a":1,"b":2,"g":"s","de":"In Mekka spaltete sich der Mond vor den Augen der Menschen. Die Quraisch sagten: Das ist Zauberei – fragt die Reisenden! Die Reisenden bestätigten es. Die Verse: Die Stunde ist nahegekommen und der Mond hat sich gespalten; sehen sie ein Zeichen, wenden sie sich ab.","src":"Buchārī 3868, Muslim 2802","w":286},{"s":54,"a":47,"b":49,"g":"s","de":"Götzendiener aus Quraisch stritten mit dem Propheten ﷺ über die Vorherbestimmung. Darauf kamen die Verse: Wir haben jedes Ding nach Maß erschaffen.","src":"Muslim 2656 – Abū Huraira","w":287},{"s":56,"a":28,"b":28,"g":"w","de":"Muslime bewunderten in einem fruchtbaren Tal bei Ṭāʾif die Lotusbäume und sagten: Hätten wir doch so etwas! Der Vers beschreibt die Gärten des Paradieses: unter dornenlosen Lotusbäumen.","w":289},{"s":56,"a":39,"b":40,"g":"w","de":"Als Vers 13–14 kam (eine große Schar von den Früheren und wenige von den Späteren), weinte ʿUmar: Wir glauben an dich, und doch werden nur wenige von uns gerettet? Dann kamen Vers 39–40: eine große Schar von den Früheren und eine große Schar von den Späteren.","w":288},{"s":56,"a":75,"b":82,"g":"s","de":"Nach einem Regen sagte der Prophet ﷺ: Heute Morgen sind manche dankbar und manche undankbar aufgewacht – die einen sagten „Das ist Allahs Gnade“, die anderen „Das kam durch diesen Stern“. Darauf kamen die Verse bis: Macht ihr das Leugnen zu eurem Anteil?","src":"Muslim 73 – Ibn ʿAbbās","w":291},{"s":57,"a":10,"b":10,"g":"w","de":"Der Vers ehrt jene, die schon vor der Befreiung Mekkas, als die Muslime wenige und schwach waren, gespendet und gekämpft haben – nach al-Kalbī besonders Abū Bakr, der damals sein ganzes Vermögen gab. Sie stehen höher als die, die erst später spendeten; doch allen hat Allah das Beste versprochen.","w":292},{"s":57,"a":16,"b":16,"g":"w","de":"Nach Ibn Masʿūd vergingen nur vier Jahre zwischen ihrem Islam und diesem Vers, der die Gläubigen sanft ermahnt: Ist es nicht Zeit, dass die Herzen der Gläubigen demütig werden beim Gedenken Allahs?","src":"Muslim 3027","w":293},{"s":58,"a":1,"b":4,"g":"w","de":"Khaula bint Thaʿlaba kam zum Propheten ﷺ und klagte: Mein Mann hat sich im Zorn mit einem alten Schwur der Araber („Du bist mir wie der Rücken meiner Mutter“) von mir getrennt – und ich bin alt und habe kleine Kinder. Allah hörte ihre Klage und offenbarte: Allah hat das Wort derer gehört, die mit dir über ihren Mann stritt. Die Verse regeln die Sühne dafür.","src":"Abū Dāwūd 2214; Buchārī, at-Tauḥīd, muʿallaq","w":297},{"s":58,"a":8,"b":10,"g":"w","de":"Einige tuschelten heimlich, wenn Gläubige vorbeigingen, sodass diese sich sorgten, es gebe schlechte Nachrichten von ihren Angehörigen auf Feldzügen. Trotz Verbot taten sie es weiter. Die Verse verbieten heimliches Gerede zur Sünde – sprecht heimlich nur über Gutes.","w":299},{"s":58,"a":11,"b":11,"g":"w","de":"An einem Freitag war die Versammlung beim Propheten ﷺ voll. Gefährten, die bei Badr gekämpft hatten, kamen später und standen, weil niemand Platz machte. Der Prophet ﷺ bat einige, aufzustehen. Der Vers kam: Wenn euch gesagt wird „Macht Platz“, dann macht Platz – Allah wird euch Raum schaffen.","w":294},{"s":58,"a":12,"b":13,"g":"w","de":"Manche führten sehr lange private Gespräche mit dem Propheten ﷺ, sodass die Armen kaum zu ihm kamen. Allah befahl, vor einem solchen Gespräch eine Spende zu geben. ʿAlī war der Einzige, der es tat; dann kam schon die Erleichterung in Vers 13.","src":"Tirmidhī 3300","w":295},{"s":58,"a":14,"b":19,"g":"w","de":"Ein Heuchler saß beim Propheten ﷺ und trug danach alles zu dessen Gegnern. Zur Rede gestellt, schwor er, nichts gesagt zu haben. Die Verse beschreiben solche Leute: Sie schwören falsch, obwohl sie es wissen.","w":296},{"s":58,"a":22,"b":22,"g":"w","de":"Der Vers beschreibt Gläubige, die die Liebe zu Allah und Seinem Gesandten über alles stellen, selbst über Väter, Söhne, Brüder und Sippe – die Überlieferungen nennen Gefährten, die bei Badr und Uḥud gegen eigene Verwandte standen. Allah hat den Glauben in ihre Herzen geschrieben.","w":298},{"s":59,"a":1,"b":6,"g":"w","de":"Der Stamm Banū Naḍīr in Medina hatte einen Vertrag mit dem Propheten ﷺ, brach ihn aber nach Uḥud. Die Muslime belagerten ihre Festungen, bis sie abzogen und mitnahmen, was ihre Kamele tragen konnten. Die ersten Verse von al-Ḥaschr erzählen davon.","src":"Vgl. Buchārī 4882–4884","w":300},{"s":59,"a":9,"b":9,"g":"s","de":"Ein hungriger Gast kam zum Propheten ﷺ. Ein Mann der Anṣār nahm ihn mit nach Hause; seine Frau hatte nur das Essen der Kinder. Sie brachten die Kinder schlafen, löschten die Lampe und taten so, als äßen sie mit, damit der Gast satt wurde. Am Morgen sagte der Prophet ﷺ: Allah hat sich über euch gefreut – und der Vers kam: Sie ziehen andere sich selbst vor, auch wenn sie selbst in Not sind.","src":"Buchārī 3798, Muslim 2054","w":301},{"s":60,"a":7,"b":8,"g":"s","de":"Die Gläubigen sagten sich von ihren götzendienerischen Verwandten los, was ihnen schwer fiel. Allah tröstete: Vielleicht stiftet Allah Liebe zwischen euch und ihnen – und viele nahmen tatsächlich den Islam an. Vers 8 erlaubt Güte gegenüber allen, die nicht gegen euch kämpfen; so durfte Asmāʾ ihre nichtmuslimische Mutter gut behandeln.","src":"Buchārī 2620","w":304},{"s":60,"a":10,"b":11,"g":"s","de":"Nach dem Vertrag von Ḥudaibiya flohen einige gläubige Frauen aus Mekka nach Medina, und ihre Familien forderten sie zurück. Der Vers kam: Wenn gläubige Frauen als Auswanderinnen zu euch kommen, prüft sie – und schickt sie nicht zu den Ungläubigen zurück.","src":"Buchārī 2711 – Umm Kulthūm bint ʿUqba","w":302},{"s":60,"a":13,"b":13,"g":"w","de":"Einige arme Muslime gaben Nachrichten an Feinde der Muslime weiter und bekamen dafür Früchte. Der Vers warnt: Nehmt nicht Leute zu Vertrauten, denen Allah zürnt.","w":303},{"s":61,"a":2,"b":4,"g":"w","de":"Gefährten sagten: Wüssten wir, welche Taten Allah am meisten liebt, wir würden sie tun. Darauf kam die Sure aṣ-Ṣaff: Warum sagt ihr, was ihr nicht tut? … Allah liebt die, die auf Seinem Weg in Reihen stehen, wie ein festgefügter Bau.","src":"Tirmidhī 3309 – ʿAbdullāh ibn Salām","w":305},{"s":62,"a":11,"b":11,"g":"s","de":"An einem Freitag hielt der Prophet ﷺ die Khuṭba, als eine Handelskarawane aus Syrien ankam. Die Leute liefen hinaus, nur zwölf Männer blieben sitzen. Darauf kam der Vers: Wenn sie einen Handel oder ein Vergnügen sehen, laufen sie dorthin und lassen dich stehen – sag: Was bei Allah ist, ist besser.","src":"Buchārī 936, Muslim 863 – Dschābir","w":306},{"s":63,"a":7,"b":8,"g":"s","de":"Auf einem Feldzug stritten zwei Männer am Wasser. ʿAbdullāh ibn Ubayy sagte darauf: Gebt nichts mehr für die Leute beim Gesandten aus – und wenn wir nach Medina zurückkehren, wird der Mächtigere den Schwächeren vertreiben. Der junge Zaid ibn Arqam erzählte es dem Propheten ﷺ; Ibn Ubayy schwor, es nicht gesagt zu haben. Dann bestätigten die Verse Zaid.","src":"Buchārī 4900, Muslim 2772","w":307},{"s":64,"a":14,"b":14,"g":"w","de":"Einige Männer in Mekka wollten nach Medina auswandern, doch Frauen und Kinder hielten sie zurück. Später sahen sie, dass andere im Wissen schon weit voraus waren, und wollten ihre Familien bestrafen. Der Vers warnt vor dem, was vom Guten abhält, sagt aber auch: Wenn ihr verzeiht und vergebt – Allah ist vergebend.","src":"Tirmidhī 3317","w":308},{"s":65,"a":2,"b":3,"g":"w","de":"ʿAuf ibn Mālik klagte, dass sein Sohn gefangen sei und die Familie in Not. Der Prophet ﷺ riet: Fürchte Allah, sei geduldig und sagt oft: Lā ḥaula wa lā quwwata illā billāh. Bald entkam der Sohn und brachte sogar Tiere mit. Dazu kam: Wer Allah fürchtet, dem schafft Er einen Ausweg und versorgt ihn, woher er es nicht erwartet.","w":309},{"s":66,"a":1,"b":4,"g":"s","de":"Der Prophet ﷺ trank gern Honig bei einer seiner Frauen. Zwei andere Frauen verabredeten aus Eifersucht, ihm zu sagen, er rieche nach Maghāfīr (einem unangenehm riechenden Harz). Da schwor er, keinen Honig mehr zu trinken. Allah offenbarte: O Prophet, warum verbietest du dir, was Allah dir erlaubt hat?","src":"Buchārī 4912, Muslim 1474 – ʿĀʾischa; al-Wāḥidī nennt eine andere Begebenheit","w":311},{"s":67,"a":13,"b":13,"g":"w","de":"Götzendiener redeten schlecht über den Propheten ﷺ und sagten zueinander: Sprecht leise, damit Muhammads Gott euch nicht hört. Der Vers: Ob ihr eure Worte verbergt oder offen sagt – Er weiß, was in den Herzen ist.","w":313},{"s":68,"a":4,"b":4,"g":"w","de":"Niemand hatte einen schöneren Charakter als der Prophet ﷺ: Wann immer ihn ein Gefährte oder jemand aus seiner Familie rief, antwortete er: Ich bin für dich da! Dazu der Vers: Du bist wahrlich von gewaltig edler Wesensart.","src":"Vgl. Muslim 746: „Sein Charakter war der Qur'an.“","w":314},{"s":68,"a":51,"b":51,"g":"w","de":"Einige Gegner wollten dem Propheten ﷺ mit dem „bösen Blick“ schaden. Der Vers: Die Ungläubigen hätten dich mit ihren Blicken fast zu Fall gebracht, als sie die Ermahnung hörten.","w":315},{"s":69,"a":12,"b":12,"g":"w","de":"Nach einer schwachen Überlieferung sagte der Prophet ﷺ zu ʿAlī, Allah habe ihm befohlen, ihn zu lehren, und es kam der Vers: … und damit ein bewahrendes Ohr es bewahre.","w":316},{"s":70,"a":1,"b":3,"g":"w","de":"An-Naḍr ibn al-Ḥārith forderte spöttisch die Strafe Allahs herbei. Darauf bezieht sich der Vers: Ein Fragender fragte nach einer Strafe, die eintreffen wird.","w":317},{"s":70,"a":36,"b":39,"g":"w","de":"Die Götzendiener scharten sich um den Propheten ﷺ, um zu spotten, und sagten: Wenn diese ins Paradies kommen, dann wir erst recht! Die Verse antworten: Hofft etwa jeder von ihnen, in den Garten der Wonne zu kommen? Keineswegs.","w":318},{"s":72,"a":1,"b":2,"g":"s","de":"Auf dem Weg zum Markt von ʿUkāẓ betete der Prophet ﷺ mit Gefährten das Fadschr-Gebet bei Nakhla. Eine Gruppe von Dschinn hörte den Qur'an und sagte: Wir haben einen wunderbaren Qur'an gehört, der zum rechten Weg leitet. Allah offenbarte die Sure al-Dschinn.","src":"Buchārī 4921, Muslim 449"},{"s":74,"a":1,"b":5,"g":"s","de":"Nach der ersten Offenbarung kam eine Pause. Dann sah der Prophet ﷺ Dschibrīl zwischen Himmel und Erde und eilte erschrocken nach Hause: Hüllt mich ein! Da kam: O du Zugedeckter, steh auf und warne, und deinen Herrn verherrliche, und deine Kleidung reinige.","src":"Buchārī 4922, Muslim 161 – Dschābir","w":320},{"s":74,"a":11,"b":26,"g":"w","de":"Al-Walīd ibn al-Mughīra hörte den Qur'an und war berührt: Bei Allah, das ist keine Dichtung, es hat Süße und Anmut. Doch Abū Dschahl drängte ihn, etwas Schlechtes darüber zu sagen, um seinen Stamm zu beruhigen. Nach langem Überlegen sagte er: Das ist nur überlieferte Zauberei. Über ihn kamen diese Verse.","w":319},{"s":75,"a":3,"b":4,"g":"w","de":"Ein Mann fragte den Propheten ﷺ nach dem Tag der Auferstehung und sagte dann: Selbst wenn ich ihn sähe, würde ich nicht glauben – kann Allah diese Knochen wirklich zusammenfügen? Der Vers antwortet: Doch, Wir vermögen sogar seine Fingerspitzen wiederherzustellen.","w":321},{"s":80,"a":1,"b":10,"g":"s","de":"Der blinde ʿAbdullāh ibn Umm Maktūm kam und bat: Lehre mich! Der Prophet ﷺ sprach gerade mit vornehmen Quraisch, die er zum Islam einlud, und wandte sich ab. Darauf kam: Er runzelte die Stirn und wandte sich ab, weil der Blinde zu ihm kam. Danach ehrte der Prophet ﷺ Ibn Umm Maktūm sehr.","src":"Tirmidhī 3331 – ʿĀʾischa"},{"s":83,"a":1,"b":3,"g":"w","de":"Als der Prophet ﷺ nach Medina kam, betrogen dort viele Händler beim Messen und Wiegen. Darauf kam: Wehe den Betrügern beim Maß! Danach maßen sie gerecht.","src":"Ibn Mādscha 2223 – Ibn ʿAbbās"},{"s":96,"a":6,"b":19,"g":"s","de":"Abū Dschahl schwor: Wenn ich Muhammad beim Niederwerfen an der Kaaba sehe, trete ich ihm auf den Nacken! Als er es versuchte, wich er erschrocken zurück – er sah zwischen sich und dem Propheten einen Graben aus Feuer und Flügel. Die Verse sagen: Hast du den gesehen, der einen Diener am Beten hindert? … Wirf dich nieder und nähere dich!","src":"Muslim 2797 – Abū Huraira"},{"s":112,"a":1,"b":4,"g":"w","de":"Die Götzendiener sagten zum Propheten ﷺ: Beschreib uns die Abstammung deines Herrn! Darauf kam die Sure al-Ikhlāṣ: Sag: Er ist Allah, der Eine … Er zeugt nicht und ist nicht gezeugt.","src":"Tirmidhī 3364 – Ubayy ibn Kaʿb"}];
